text_nat:
def print_banner(title):
    line = "=" * (len(title) + 8)
    print(line)
    print("|| %s ||" % title.upper())
    print(line)


def print_ingredients(ingredients):
    print("Ingredients (%d):" % len(ingredients))
    index = 1
    for item in ingredients:
        print("  %d. %s" % (index, item.strip()))
        index += 1
    print("")


def print_instructions(steps):
    print("Instructions:")
    number = 1
    for step in steps:
        print("  Step %d: %s" % (number, step.strip().capitalize()))
        number += 1
    print("")


def format_time(minutes):
    if minutes < 60:
        return "%d minutes" % minutes
    hours = minutes // 60
    rest = minutes % 60
    if rest == 0:
        return "%d hour(s)" % hours
    return "%d hour(s) %d minutes" % (hours, rest)


def validate(details):
    if len(details) != 4:
        raise ValueError("recipe details must have exactly 4 elements")
    name, ingredients, steps, minutes = details
    if not name:
        raise ValueError("dish name must not be empty")
    if not ingredients:
        raise ValueError("at least one ingredient is required")
    if not steps:
        raise ValueError("at least one step is required")
    if minutes <= 0:
        raise ValueError("preparation time must be positive")
    return name, ingredients, steps, minutes


def recipe(details):
    name, ingredients, steps, minutes = validate(details)
    print_banner(name)
    print("")
    print_ingredients(ingredients)
    print_instructions(steps)
    print("Preparation time: %s" % format_time(minutes))
    print("Enjoy your %s!" % name.lower())


def main():
    recipe(["Pancakes", ["flour", "milk"], ["mix", "fry"], 10])
    print("")
    recipe(["Slow Roast", ["beef", "salt", "pepper"],
            ["season the beef", "roast in the oven", "rest before slicing"], 95])
    try:
        recipe(["Mystery", [], ["wonder"], 5])
    except ValueError as error:
        print("Could not print recipe: %s" % error)


if __name__ == "__main__":
    main()

