text_nat:
def print_title():
    print("LOCAL WEATHER FORECAST")
    print("=" * 46)


def describe_day(day, condition, high, low):
    spread = high - low
    print("%-10s %-12s high %3d  low %3d" % (day, condition, high, low))
    if spread >= 20:
        print("%12swide swing of %d degrees today" % ("", spread))
    if condition.lower() in ("snow", "sleet", "ice"):
        print("%12swinter driving conditions expected" % "")


def print_daily(forecasts):
    for day, condition, high, low in forecasts:
        describe_day(day, condition, high, low)


def average(values):
    return float(sum(values)) / len(values)


def print_summary(forecasts):
    highs = [entry[2] for entry in forecasts]
    lows = [entry[3] for entry in forecasts]
    warmest = max(forecasts, key=lambda entry: entry[2])
    coldest = min(forecasts, key=lambda entry: entry[3])
    print("-" * 46)
    print("Highest temperature: %d on %s" % (warmest[2], warmest[0]))
    print("Lowest temperature:  %d on %s" % (coldest[3], coldest[0]))
    print("Average high: %.1f" % average(highs))
    print("Average low:  %.1f" % average(lows))
    freezing = [entry for entry in forecasts if entry[3] < 0]
    if freezing:
        names = ", ".join([entry[0] for entry in freezing])
        print("FREEZE WARNING: lows below zero on %s" % names)
    else:
        print("No freeze expected this week.")


def weather(forecasts):
    if not forecasts:
        print("No forecast data available.")
        return
    clean = []
    for entry in forecasts:
        if len(entry) != 4:
            print("Skipping malformed record: %s" % (entry,))
            continue
        day, condition, high, low = entry
        if low > high:
            print("Correcting reversed temperatures for %s" % day)
            high, low = low, high
        clean.append((day, condition, int(high), int(low)))
    if not clean:
        print("No usable forecast records found.")
        return
    print_title()
    print_daily(clean)
    print_summary(clean)
    print("=" * 46)
    print("Report covers %d day(s). Stay safe out there!" % len(clean))


def main():
    week = [
        ("Monday", "Sunny", 18, 7),
        ("Tuesday", "Rain", 14, 9),
        ("Wednesday", "Snow", 2, -5),
        ("Thursday", "Cloudy", 11, 3),
        ("Friday", "Windy", 24, 1),
    ]
    weather(week)


if __name__ == "__main__":
    main()

