MET_VALUES = {
    "running": 9.8,
    "cycling": 7.5,
    "swimming": 8.0,
    "walking": 3.5,
    "yoga": 2.5,
}


def print_title():
    print("WEEKLY ACTIVITY REPORT")
    print("=" * 40)


def estimate_calories(activity, minutes):
    met = MET_VALUES.get(activity.lower(), 4.0)
    return int(met * 70.0 * (minutes / 60.0))


def print_activity_log(workouts):
    print("Activity Log:")
    index = 1
    for activity, minutes in workouts:
        calories = estimate_calories(activity, minutes)
        line = "%2d. %-12s %4d min  (~%d kcal)" % (index, activity.title(), minutes, calories)
        print(line)
        index += 1
    print("-" * 40)


def print_achievements(workouts):
    total = sum(minutes for activity, minutes in workouts)
    average = total / float(len(workouts))
    print("Total duration: %d minutes" % total)
    print("Average duration: %.1f minutes" % average)
    longest = max(workouts, key=lambda pair: pair[1])
    print("Longest session: %s (%d min)" % (longest[0].title(), longest[1]))
    if total > 300:
        print("MILESTONE: you passed 300 minutes this week!")
    print("Keep moving - next week starts now!")


def validate(workouts):
    if not isinstance(workouts, list) or not workouts:
        print("No workouts recorded this week.")
        return False
    for entry in workouts:
        if len(entry) != 2:
            print("Skipping report: each entry needs an activity and a duration.")
            return False
        if not isinstance(entry[0], str) or not isinstance(entry[1], int):
            print("Skipping report: expected (str, int) pairs.")
            return False
        if entry[1] <= 0:
            print("Skipping report: durations must be positive.")
            return False
    return True


def fitness(workouts):
    if not validate(workouts):
        return
    print_title()
    print_activity_log(workouts)
    print_achievements(workouts)


def main():
    week = [
        ("running", 45),
        ("yoga", 60),
        ("cycling", 90),
        ("swimming", 75),
        ("walking", 40),
    ]
    fitness(week)
    print("")
    fitness([])


if __name__ == "__main__":
    main()

