text_nat:
UNIVERSITY_NAME = "Northfield State University"
CREDITS_PER_COURSE = 3


def letter_grade(score):
    if score >= 90:
        return "A"
    if score >= 80:
        return "B"
    if score >= 70:
        return "C"
    if score >= 60:
        return "D"
    return "F"


def grade_points(score):
    scale = {"A": 4.0, "B": 3.0, "C": 2.0, "D": 1.0, "F": 0.0}
    return scale[letter_grade(score)]


def print_header():
    print("=" * 46)
    print(UNIVERSITY_NAME.center(46))
    print("Office of the Registrar".center(46))
    print("=" * 46)
    print("OFFICIAL ACADEMIC TRANSCRIPT".center(46))
    print("")


def print_courses(grades):
    print("%-26s %6s %7s" % ("COURSE", "SCORE", "GRADE"))
    print("-" * 46)
    for course, score in grades:
        print("%-26s %6.1f %7s" % (course, score, letter_grade(score)))
    print("-" * 46)


def compute_gpa(grades):
    if not grades:
        return 0.0
    total = 0.0
    for course, score in grades:
        total += grade_points(score)
    return total / len(grades)


def print_standing(grades):
    credits = len(grades) * CREDITS_PER_COURSE
    gpa = compute_gpa(grades)
    print("Courses completed: %d" % len(grades))
    print("Total credits completed: %d" % credits)
    print("Grade point average: %.2f" % gpa)
    if gpa >= 3.75:
        print("HONORS STATUS: Summa Cum Laude")
    elif gpa >= 3.5:
        print("HONORS STATUS: Magna Cum Laude")
    elif gpa >= 3.25:
        print("HONORS STATUS: Cum Laude")
    print("")
    print("[ * OFFICIAL SEAL OF %s * ]" % UNIVERSITY_NAME.upper())


def transcript(grades):
    clean = []
    for course, score in grades:
        if score < 0 or score > 100:
            print("Rejected invalid score for %s: %s" % (course, score))
        else:
            clean.append((course, float(score)))
    print_header()
    print_courses(clean)
    print_standing(clean)
    return compute_gpa(clean)


def main():
    record = [
        ("Linear Algebra", 94),
        ("Organic Chemistry", 88),
        ("World History", 91),
        ("Introductory Latin", 79),
        ("Astrophysics", 105),
    ]
    final_gpa = transcript(record)
    print("Returned GPA value: %.2f" % final_gpa)


if __name__ == "__main__":
    main()

