text_nat:
def booking_reference(flights):
    total = 0
    for origin, destination, duration in flights:
        for ch in origin + destination:
            total += ord(ch)
        total += duration
    letters = "ABCDEFGHJKLMNPQRSTUVWXYZ"
    code = ""
    value = total
    for position in range(3):
        code += letters[value % len(letters)]
        value //= len(letters)
    return "%s%04d" % (code, total % 10000)


def format_duration(minutes):
    hours = minutes // 60
    rest = minutes % 60
    if hours == 0:
        return "%dm" % rest
    return "%dh %02dm" % (hours, rest)


def print_header(reference):
    print("=" * 46)
    print("        SKYLARK AIRLINES - TRAVEL DOCUMENT")
    print("=" * 46)
    print("Booking reference: %s" % reference)
    print("")


def print_legs(flights):
    print("ITINERARY")
    print("-" * 46)
    leg_number = 1
    for origin, destination, duration in flights:
        print("Leg %d: %-12s -> %-12s %s" % (leg_number, origin, destination,
                                             format_duration(duration)))
        leg_number += 1
    print("")


def print_summary(flights):
    total_minutes = 0
    for origin, destination, duration in flights:
        total_minutes += duration
    layovers = max(len(flights) - 1, 0)
    print("SUMMARY")
    print("-" * 46)
    print("Total travel time: %s" % format_duration(total_minutes))
    if layovers == 1:
        print("Layovers: 1 stop")
    else:
        print("Layovers: %d stops" % layovers)
    print("Reminder: one carry-on bag and one checked bag per passenger.")
    print("Bon voyage!")


def itinerary(flights):
    if not flights:
        print("No flights booked - nothing to print.")
        return
    for entry in flights:
        if len(entry) != 3:
            raise ValueError("each flight needs origin, destination, duration")
    reference = booking_reference(flights)
    print_header(reference)
    print_legs(flights)
    print_summary(flights)


def main():
    trip = [
        ("Lisbon", "Madrid", 85),
        ("Madrid", "Vienna", 160),
        ("Vienna", "Helsinki", 145),
    ]
    itinerary(trip)
    print("")
    itinerary([("Oslo", "Bergen", 50)])


if __name__ == "__main__":
    main()

