def print_title():
    print("=" * 40)
    print("HARDWARE DIAGNOSTIC UTILITY v1.0")
    print("=" * 40)
    print("Scanning attached temperature sensors...")


def validate(sensors):
    clean = []
    for entry in sensors:
        if len(entry) != 2:
            print("Skipping malformed entry: %r" % (entry,))
            continue
        name, temp = entry
        try:
            clean.append((str(name), int(temp)))
        except (TypeError, ValueError):
            print("Skipping non-numeric reading for sensor %s" % name)
    return clean


def print_readings(sensors):
    print("-" * 40)
    print("SENSOR READINGS")
    for name, temp in sensors:
        print("  %-20s %4d C" % (name, temp))
    print("-" * 40)


def average_temperature(sensors):
    total = 0
    for name, temp in sensors:
        total += temp
    return float(total) / len(sensors)


def safety_check(sensors):
    hot = []
    for name, temp in sensors:
        if temp > 80:
            print("  WARNING: %s is running hot at %d C!" % (name, temp))
            hot.append(name)
    if not hot:
        print("  All sensors within safe operating range.")
    average = average_temperature(sensors)
    print("  Average temperature: %.1f C" % average)
    if hot:
        print("  Cooling fan status: MAXIMUM (%d sensor(s) overheating)" % len(hot))
    elif average > 60:
        print("  Cooling fan status: ELEVATED")
    else:
        print("  Cooling fan status: NORMAL")
    return hot


def diagnostic(sensors):
    print_title()
    readings = validate(sensors)
    if not readings:
        print("No usable sensor data found. Diagnostic aborted.")
        return
    print_readings(readings)
    print("SAFETY CHECK")
    hot = safety_check(readings)
