def is_fragile(item_name):
    return item_name.strip().lower() in FRAGILE_ITEMS


def normalize_order(order):
    item_name, quantity = order
    name = str(item_name).strip()
    if not name:
        raise ValueError("order is missing an item name")
    count = int(quantity)
    if count < 1:
        raise ValueError("quantity for %s must be at least 1" % name)
    return name, count


def build_item(item_name, index, total):
    print("%s being constructed (%d of %d)" % (item_name, index, total))
    if is_fragile(item_name):
        print("handle with care")


def process_order(order):
    name, count = normalize_order(order)
    if count > BULK_THRESHOLD:
        print("warning: bulk order of %d units" % count)
    print("starting conveyor belt")
    print("reading barcode")
    for position in range(1, count + 1):
        build_item(name, position, count)
    print("quality check passed")
    return count


def assemble(orders):
    print("powering on factory")
    if not orders:
        print("no items to process")
    produced = 0
    for order in orders:
        try:
            produced += process_order(order)
        except (ValueError, TypeError) as problem:
            print("skipping order: %s" % problem)
    print("shutting down conveyor")
    print("total units produced: %d" % produced)
    print("end of shift")
    return produced


