def format_duration(seconds):
    minutes = seconds // 60
    return "%d:%02d" % (minutes, seconds % 60)


def validate_entry(entry):
    if len(entry) != 3:
        return "entry must have artist, title and duration"
    if not isinstance(entry[2], int):
        return "duration must be an integer number of seconds"
    if entry[2] <= 0:
        return "duration must be positive"
    return None


def play(playlist):
    print("initializing audio device")
    if not playlist:
        print("nothing to play")
        return 0
    played = 0
    for entry in playlist:
        problem = validate_entry(entry)
        if problem is not None:
            print("invalid track: %s" % problem)
            continue
        artist, title, duration = entry
        print("now playing %s - %s" % (artist, title))
        print("duration %s" % format_duration(duration))
        if duration > 300:
            print("skipping long track")
        else:
            print("track finished")
            played += 1
        if artist.lower() == "classical":
            print("adjusting equalizer for classical")
    print("playlist complete")
    print("entering sleep mode")
    return played


def total_time(playlist):
    total = 0
    for entry in playlist:
        if validate_entry(entry) is None:
            total += entry[2]
    return total


def report(playlist, played):
    print("tracks in playlist: %d" % len(playlist))
    print("tracks completed: %d" % played)
    print("total listening time available: %s" % format_duration(total_time(playlist)))


