def normalize(exercises):
    """Return a cleaned list of exercise names, dropping blanks."""
    cleaned = []
    for item in exercises:
        name = str(item).strip().lower()
        if name:
            cleaned.append(name)
    return cleaned


def needs_shoes(exercise):
    return "jump" in exercise


def coach(exercises):
    """Guide the user through the given list of exercises."""
    plan = normalize(exercises)
    print("stretching muscles")
    if not plan:
        print("rest day today")
    for exercise in plan:
        print("get ready for " + exercise)
        if needs_shoes(exercise):
            print("wear supportive shoes")
        if exercise == "plank":
            print("keep your core tight")
        print("take a short breather")
    print("great job today")
    print("drink plenty of water")
    return len(plan)


def summarize(exercises):
    """Report how the requested session breaks down before it starts."""
    plan = normalize(exercises)
    skipped = len(exercises) - len(plan)
    print("session size: %d" % len(plan))
    if skipped:
        print("ignored %d blank entry/entries" % skipped)
    jumping = [name for name in plan if needs_shoes(name)]
    if jumping:
        print("high impact moves: " + ", ".join(jumping))


def run_session(title, exercises):
    print("=== %s ===" % title)
    summarize(exercises)
