REACTIONS = {
    "feed": ["The pet eats happily."],
    "play": ["The pet runs around."],
    "scold": ["The pet looks sad."],
    "bath": ["The pet shakes off water.", "Drying the pet with a towel."],
}


def normalize(action):
    """Turn a raw user action into a comparable keyword."""
    if not isinstance(action, str):
        action = str(action)
    return action.strip().lower()


def wake_up():
    print("The pet wakes up.")


def fall_asleep():
    print("The pet falls asleep.")


def react(action):
    """Print the pet's reaction; return True if the action was understood."""
    lines = REACTIONS.get(action)
    if lines is None:
        print("The pet tilts its head, confused.")
        return False
    for line in lines:
        print(line)
    return True


def summarize(understood, ignored):
    print("Understood %d action(s), ignored %d." % (understood, ignored))


def interact(actions):
    """Run a full session with the virtual pet and report what happened."""
    wake_up()
    if actions is None:
        actions = []
    if not actions:
        print("The pet goes back to sleep.")
        return {"understood": 0, "ignored": 0}
    understood = 0
    ignored = 0
    for raw in actions:
        if react(normalize(raw)):
            understood += 1
        else:
            ignored += 1
    print("The pet is tired.")
    fall_asleep()
    summarize(understood, ignored)
    return {"understood": understood, "ignored": ignored}


def main():
    sessions = [
        ["feed", "play"],
        [],
        ["Bath", "scold", "dance"],
    ]
    for actions in sessions:
        print("=== Session with %d action(s) ===" % len(actions))
        result = interact(actions)
        if result["ignored"]:
