def turn_on_ovens():
    print("turning on ovens")


def close_kitchen():
    print("closing kitchen")


def dust_flour():
    print("dusting flour")


def roll_dough(size):
    print("rolling dough for a %s" % size)


def apply_topping(topping):
    if topping == "cheese":
        print("extra mozzarella added")
    elif topping == "pepperoni":
        print("slicing spicy pepperoni")
    elif topping == "veggie":
        print("chopping fresh vegetables")


def bake():
    print("baking in oven")


def finish_service():
    print("boxing orders")
    print("ready for delivery")


def check_order(order):
    if len(order) != 2:
        raise ValueError("each pizza needs a size and a topping, got %r" % (order,))
    size, topping = order
    if not size:
        raise ValueError("missing size in %r" % (order,))
    return size, topping


def make_pizza(order):
    size, topping = check_order(order)
    dust_flour()
    roll_dough(size)
    apply_topping(topping)
    bake()


def prepare(pizzas):
    turn_on_ovens()
    if not pizzas:
        close_kitchen()
        return 0
    for order in pizzas:
