def normalize(directories):
    """Strip whitespace from folder names and drop empty entries."""
    cleaned = []
    for name in directories:
        trimmed = str(name).strip()
        if trimmed:
            cleaned.append(trimmed)
    return cleaned


def announce_start():
    print("Initiating backup protocol...")


def scan(directory):
    print("Scanning folder: %s" % directory)


def handle_special(directory):
    """Emit the extra step required by certain well-known folders."""
    key = directory.lower()
    if key == "system":
        print("Requiring administrator privileges...")
        return True
    if key == "media":
        print("Compressing large video files...")
        return True
    if key == "logs":
        print("Archiving old records...")
        return True
    return False


def checksum(directory):
    """Cheap deterministic stand-in for a real file checksum."""
    total = 0
    for position, character in enumerate(directory):
        total = (total + (position + 1) * ord(character)) % 65536
    return total


def finalize(processed):
    print("Calculating checksums...")
    for directory in processed:
        print("  %s -> %04x" % (directory, checksum(directory)))
    print("Uploading to cloud...")
