        if count < 0 or count > 4:
            raise ValueError("row %d holds an impossible count: %d" % (index + 1, count))
        cleaned.append(count)
    return cleaned


def check_row(number, count):
    print "checking restraints for row %d" % number
    if count == 0:
        print "row is empty"
    if count == 4:
        print "row is fully loaded"
    print "pulling down lap bar"
    print "tugging seatbelt"
    return count


def clear_station():
    print "clearing the station"
    print "sounding dispatch horn"
    print "releasing brakes"


def summarize(seated, rows_checked):
    capacity = rows_checked * 4
    print "seated %d of %d riders" % (seated, capacity)
    if capacity > 0:
        share = 100.0 * seated / capacity
        print "train filled to %.1f%% of capacity" % share


def launch(rows):
    counts = validate(rows)
    print "loading passengers"
    if not counts:
        print "running empty train"
    seated = 0
    for offset, count in enumerate(counts):
        seated += check_row(offset + 1, count)
    clear_station()
    return seated


def main():
    trains = [[4, 2, 0, 3], []]
    for cycle, rows in enumerate(trains):
        print "=== dispatch cycle %d ===" % (cycle + 1)
        seated = launch(rows)
        summarize(seated, len(rows))
    try:
        launch([4, 5])
    except ValueError as error:
        print "dispatch aborted: %s" % error


if __name__ == "__main__":
    main()

