def port_scan(target):
    open_ports = [22, 80]
    if len(target) > 12:
        open_ports.append(443)

    msg = "Port scan results for {0}: {1} open ports".format(target, len(open_ports))
    print(msg)
    return open_ports

def vulnerability_probe(target):
    vuln_count = 0
    if target.endswith(".1"):
        vuln_count = 3
    elif target.endswith(".2"):
        vuln_count = 1

    msg = "Vulnerability probe for {0}: {1} issues found".format(target, vuln_count)
    print(msg)
    return vuln_count

def brute_force(target):
    breached = False
    if target.endswith(".1"):
        breached = True

    if breached:
        print("Brute force attempt for {0}: SUCCESS".format(target))
    else:
        print("Brute force attempt for {0}: FAILED".format(target))
    return breached

def calculate_grade(vulns, breached):
    if breached:
        return "F"
    if vulns > 2:
        return "D"
    if vulns > 0:
        return "B"
    return "A"

def audit(targets):
    for target in targets:
        print("=======================================")
        print("Initialization Banner for: {0}".format(target))

        if target.startswith("10."):
            print("Internal network bypass applied for {0}".format(target))
            print("Final security grade for {0}: N/A (Bypassed)".format(target))
            continue

        port_scan(target)
        vulns = vulnerability_probe(target)
        breached = brute_force(target)

        final_grade = calculate_grade(vulns, breached)
        print("Final security grade for {0}: {1}".format(target, final_grade))

def main():
    test_targets = [
        "192.168.1.1",
        "10.0.0.5",
        "8.8.8.8",
        "192.168.1.254"
    ]
    audit(test_targets)

if __name__ == "__main__":
    main()

