import time

MORNING_GREETING = "Manager on duty: good morning, team."


def current_time_stamp():
    """Return the opening-time stamp used in the morning briefing."""
    return time.strftime("%H:%M")


def normalize(departments):
    """Clean up the section list: strip blanks and drop empty entries."""
    cleaned = []
    for name in departments:
        label = str(name).strip()
        if label:
            cleaned.append(label)
    return cleaned


def greet():
    """General manager greeting plus the time check."""
    print(MORNING_GREETING)
    print("Time check: %s -- opening procedure starts now." % current_time_stamp())


def open_section(name):
    """Run the standard opening steps for a single section."""
    print("[%s] Turning on the lights." % name)
    print("[%s] Booting up the registers." % name)
    print("[%s] Restocking the shelves." % name)
    if name.lower() == "bakery":
        print("[%s] Preheating the ovens." % name)


def open_doors(count):
    """Final step: doors open, customers welcome."""
    print("%d section(s) ready." % count)
    print("The main doors are unlocked.")
    print("Welcome to our first customers of the day!")


def unlock(departments):
    """Walk the whole store through its morning opening routine."""
    sections = normalize(departments)
    greet()
    if not sections:
        print("No sections listed -- nothing to open this morning.")
        return sections
    for name in sections:
        open_section(name)
    open_doors(len(sections))
    return sections


def main():
    store = ["Produce", "Bakery", " Deli ", "", "Electronics"]
    opened = unlock(store)
    print("Opening log: %s" % ", ".join(opened))


if __name__ == "__main__":
    main()

