BASE_STATS = {"strength": 8, "agility": 8, "intellect": 8, "vitality": 8}

SKILL_EFFECTS = {
    "swordplay": ("strength", 4, "Your blade arm thickens; parries come without thought."),
    "archery": ("agility", 4, "Your eyes learn distance, and your fingers learn patience."),
    "magic": ("intellect", 5, "Arcane sigils burn themselves into your memory."),
    "stealth": ("agility", 3, "Shadows lean toward you and muffle every footfall."),
    "healing": ("vitality", 3, "Wounds knit faster under your hands, yours included."),
    "smithing": ("strength", 2, "Hammer callouses make armour feel like linen."),
}


def normalize(traits):
    cleaned = []
    for trait in traits:
        key = str(trait).strip().lower()
        if key in SKILL_EFFECTS and key not in cleaned:
            cleaned.append(key)
        elif key not in SKILL_EFFECTS:
            print("The loremasters know no skill called '%s'; it is ignored." % key)
    return cleaned


def roll_base_stats():
    stats = dict(BASE_STATS)
    print("Rolling base statistics from the ancient dice...")
    for name in sorted(stats):
        print("  %-9s %2d" % (name.capitalize(), stats[name]))
    return stats


def apply_skill(stats, skill):
    attribute, bonus, flavour = SKILL_EFFECTS[skill]
    stats[attribute] = stats[attribute] + bonus
    print("Training in %s:" % skill)
    print("  %s" % flavour)
    print("  %s rises by %d to %d." % (attribute.capitalize(), bonus, stats[attribute]))
    return stats


def warn_about_mana(stats):
    mana = stats["intellect"] * 10
    print("WARNING: every spell drains your mana pool of %d points." % mana)
    print("Exhaust it and the weave will drink from your vitality instead.")
    return mana


def summarize(stats, skills):
    power = sum(stats.values())
    print("--- Character Summary ---")
    for name in sorted(stats):
        print("  %-9s %2d" % (name.capitalize(), stats[name]))
    if skills:
        print("  Skills:   %s" % ", ".join(skills))
    else:
        print("  Skills:   none, a blank slate of a hero")
    print("  Total power rating: %d" % power)
    return power


def generate(traits):
    print("Welcome to the realm of Aethermoor, traveller!")
    skills = normalize(traits)
    stats = roll_base_stats()
    for skill in skills:
        apply_skill(stats, skill)
    if "magic" in skills:
        warn_about_mana(stats)
    power = summarize(stats, skills)
    print("Your adventure begins at the gates of Greyhollow. Will you enter? (y/n)")
    return {"stats": stats, "skills": skills, "power": power}


def main():
    hero = generate(["Swordplay", "magic", "cooking", "stealth"])
    print("Hero forged with %d skills." % len(hero["skills"]))
    squire = generate(["archery", "healing"])
    if squire["power"] < hero["power"]:
        print("The squire trails the hero by %d power." % (hero["power"] - squire["power"]))


if __name__ == "__main__":
    main()

