text_nat:
MAX_ALTITUDE = 400


def preflight_check():
    """Run the preflight checklist and report each subsystem."""
    checks = [("battery", 98), ("rotors", 4), ("gps signal", 11)]
    print("--- preflight check ---")
    for name, value in checks:
        if name == "battery":
            print("battery: %d%% charged" % value)
        elif name == "rotors":
            print("rotors: %d of 4 spinning freely" % value)
        else:
            print("gps signal: locked on %d satellites" % value)
    print("preflight check complete")


def validate(waypoints):
    """Return the waypoints as floats, rejecting anything unusable."""
    cleaned = []
    for point in waypoints:
        try:
            altitude = float(point)
        except (TypeError, ValueError):
            print("skipping unreadable waypoint %r" % (point,))
            continue
        if altitude < 0:
            print("skipping negative waypoint %.1f m" % altitude)
            continue
        cleaned.append(altitude)
    return cleaned


def move(current, target):
    """Announce the vertical move and return the altitude actually reached."""
    if target > current:
        print("ascending from %.1f m to %.1f m" % (current, target))
    elif target < current:
        print("descending from %.1f m to %.1f m" % (current, target))
    else:
        print("holding altitude at %.1f m" % current)
    if target > MAX_ALTITUDE:
        print("WARNING: maximum height of %d m exceeded" % MAX_ALTITUDE)
        print("automatic descent engaged to %d m" % MAX_ALTITUDE)
        return float(MAX_ALTITUDE)
    return target


def land(current):
    """Bring the craft down from its last altitude and power off."""
    print("--- landing sequence ---")
    for step in (current / 2.0, current / 4.0, 0.0):
        print("descending to %.1f m" % step)
    print("touchdown confirmed")
    print("motors off, power down complete")


def fly(waypoints):
    preflight_check()
    route = validate(waypoints)
    if not route:
        print("no valid waypoints, flight aborted")
        return []
    altitude = 0.0
    flown = []
    for index, target in enumerate(route, 1):
        print("waypoint %d of %d" % (index, len(route)))
        altitude = move(altitude, target)
        flown.append(altitude)
    print("route complete after %d waypoints" % len(flown))
    land(altitude)
    return flown


def main():
    reached = fly([50, 120, 450, 380, 380, -10, "up", 90])
    print("altitudes reached: %s" % ", ".join("%.1f" % a for a in reached))


if __name__ == "__main__":
    main()

