def introduce():
    print("The crowd hushes as the handler and her border collie stride onto the turf.")
    print("They pause at the starting line, leash off, eyes locked together.")
    print("The judge raises a hand... and the run is on!")


def approach(name, index):
    print("Obstacle %d: heading for the %s at full stretch." % (index, name))


def execute(name):
    moves = {
        "weave poles": "slaloming through with a rhythm you could set a metronome to",
        "tunnel": "vanishing into the dark and bursting out the far end",
        "a-frame": "scrambling up the slope and controlling the descent",
        "teeter totter": "stepping on and riding the plank down to the ground",
        "tire jump": "threading the hoop without brushing a single edge",
    }
    action = moves.get(name, "clearing the %s cleanly" % name)
    print("And there it is - %s!" % action)


def crowd_reaction(index):
    if index % 3 == 0:
        print("A roar goes up from the far side of the ring!")
    elif index % 3 == 1:
        print("Applause ripples along the rail.")
    else:
        print("The crowd gasps, then cheers.")


def teeter_moment():
    print("Everything slows down here...")
    print("The plank hangs level, the dog holds position, waiting for gravity.")
    print("Thunk! Contact made, and the judges see no fault.")


def score_run(count):
    seconds = round(4.5 * count + 6.2, 2)
    faults = count // 5
    points = max(0, 100 - faults * 5)
    return seconds, faults, points


