def validate_depths(depths):
    """Return the usable depths, reporting the entries that make no sense."""
    clean = []
    for entry in depths:
        try:
            depth = float(entry)
        except (TypeError, ValueError):
            print("Ignoring unreadable depth value: %r" % (entry,))
            continue
        if depth <= 0:
            print("Ignoring non-positive depth: %g m" % depth)
            continue
        clean.append(depth)
    return clean


def pressure_at(depth):
    """Absolute pressure in atmospheres at the given depth."""
    return 1.0 + depth / 10.0


def temperature_at(depth):
    """External water temperature in degrees Celsius."""
    return max(4.0, 18.0 - 0.012 * depth)


def sonar_ping(depth):
    """Describe the sonar echo returned at the given depth."""
    delay = 2.0 * depth / 1500.0
    if depth < 500:
        return "surface clutter, echo in %.2f s" % delay
    if depth < 2000:
        return "open water, echo in %.2f s" % delay
    if depth < 4000:
        return "soft contact on the slope, echo in %.2f s" % delay
    return "no return, seabed beyond range"


def dive(depths):
    print("Hatch sealed and pressure-locked.")
    print("Ballast tanks flooding, trim neutral.")
    targets = validate_depths(depths)
    for depth in targets:
        print("--- Holding at %g m ---" % depth)
        print("Pressure reading: %.1f atm" % pressure_at(depth))
        print("External temperature: %.1f C" % temperature_at(depth))
        print("Sonar ping: %s" % sonar_ping(depth))
        if depth < 2000:
            print("Depth below 2000 m: exterior spotlights activated.")
    if targets:
        print("Maximum depth reached: %g m" % max(targets))
    else:
        print("No valid depth intervals, dive profile empty.")
    print("Ascent initiated, blowing ballast.")
    print("Surface reached, hatch may be opened.")


def main():
    profile = [250, 900, 2000, "1500", -80, 4200, "deep"]
    print("Dive profile requested: %s" % (profile,))
    dive(profile)


if __name__ == "__main__":
    main()

