def normalize(sections):
    """Clean up the incoming family names and drop blanks/duplicates."""
    cleaned = []
    for name in sections:
        label = str(name).strip().lower()
        if not label:
            print("Skipping an empty entry on the stage plot.")
            continue
        if label in cleaned:
            print("%s is already on the stage plot; skipping." % label.capitalize())
            continue
        cleaned.append(label)
    return cleaned


def leader_of(family):
    leaders = {
        "strings": "concertmaster",
        "woodwinds": "principal flute",
        "brass": "principal trumpet",
        "percussion": "principal percussionist",
    }
    return leaders.get(family, "section leader")


def open_house():
    print("Stage manager: opening the curtains.")
    print("Oboe: sounding a long, steady A440 tuning note.")


def tune_section(family):
    leader = leader_of(family)
    print("The %s of the %s section stands up." % (leader, family))
    print("The %s section matches its pitch to the oboe's A." % family)
    if family == "percussion":
        print("Special check: the timpanist tests the timpani pedals.")
        print("Timpani pedals glide smoothly through the whole range.")
    print("The %s section is seated and ready." % family)


def close_house(tuned_count):
    if tuned_count == 0:
        print("No sections were tuned, so the stage stays dark tonight.")
        return
    print("The conductor enters the stage.")
    print("The audience bursts into applause.")


def tune(sections):
    families = normalize(sections)
    open_house()
    for family in families:
        tune_section(family)
    close_house(len(families))
    return families


