def difficulty_of(trick):
    name = trick.lower()
    score = 5.0
    if "twist" in name:
        score += 2.5
    if "double" in name:
        score += 1.5
    if "layout" in name:
        score += 0.8
    return score


def has_twist(trick):
    return "twist" in trick.lower()


def introduce():
    print("Ladies and gentlemen, the gymnast steps onto the floor.")
    print("She raises both arms and waits for the music.")


def salute(direction):
    print("She turns toward the %s judge and salutes." % direction)


def takeoff(trick):
    print("Takeoff for the %s: a sharp punch off both feet." % trick)


def aerial_form(trick):
    if has_twist(trick):
        print("In the air she pulls tight and spins through the %s." % trick)
    else:
        print("In the air she holds a clean shape for the %s." % trick)


def landing_stability(trick, index):
    if index % 2 == 0:
        print("She sticks the landing of the %s without a step." % trick)
        return 0.0
    print("She takes a small hop on the landing of the %s." % trick)
    return 0.3


def twist_remark(trick):
    print("The judges note that the %s is a high difficulty element." % trick)


def cheer(count):
    print("The crowd rises after %d elements and cheers." % count)


def show_score(total, deductions):
    final = total - deductions
    print("Difficulty total: %.1f" % total)
    print("Deductions: %.1f" % deductions)
    print("Final score: %.2f" % final)


def call(tricks):
    introduce()
    salute("head")
    total = 0.0
    deductions = 0.0
    for index, trick in enumerate(tricks):
        takeoff(trick)
        aerial_form(trick)
        deductions += landing_stability(trick, index)
        total += difficulty_of(trick)
        if has_twist(trick):
            twist_remark(trick)
    salute("side")
    cheer(len(tricks))
    show_score(total, deductions)
    return total - deductions


routine = ["round-off", "back handspring", "double back tuck",
           "full twist layout", "double twist"]
result = call(routine)
print("The routine is recorded with %.2f points." % result)

