    "quartzite": 8,
}

BASE_RPM = 1200


def startup():
    print("Generator online: 480V bus energized.")
    print("Drill bit lubrication cycle complete.")


def hardness_of(rock):
    return HARDNESS.get(rock.lower(), 5)


def rotation_speed(hardness):
    speed = BASE_RPM - hardness * 90
    if speed < 300:
        speed = 300
    return speed


def analyze(rock):
    hardness = hardness_of(rock)
    print("Hardness analysis of %s: Mohs %d." % (rock, hardness))
    return hardness


def adjust_rotation(hardness):
    speed = rotation_speed(hardness)
    print("Rotation speed adjusted to %d RPM." % speed)
    return speed


def clear_debris(rock):
    print("Debris cleared: %s cuttings flushed to surface." % rock)


def handle_granite():
    print("WARNING: high friction detected on granite face.")
    print("Coolant flush engaged for 45 seconds.")


def shutdown(depth):
    print("Drill string retracted from %d meters." % depth)
    print("Core sample extracted and sealed in %d containers." % depth)


def drill(strata):
    if not strata:
        print("No strata supplied: nothing to drill.")
        return []

    startup()
    log = []
    for rock in strata:
        hardness = analyze(rock)
        speed = adjust_rotation(hardness)
        clear_debris(rock)
