def leader_and_margin(votes):
    ranked = sorted(votes.items(), key=lambda pair: pair[1], reverse=True)
    leader, top = ranked[0]
    if len(ranked) > 1:
        margin = top - ranked[1][1]
    else:
        margin = top
    return leader, margin


def remaining_ballots(votes, reporting):
    counted = sum(votes.values())
    if reporting <= 0:
        return counted
    expected_total = counted * 100.0 / reporting
    return int(round(expected_total - counted))


def validate_district(entry, index):
    if not isinstance(entry, dict):
        raise TypeError("district #%d must be a mapping" % index)
    name = entry.get("name", "District %d" % index)
    reporting = float(entry["reporting"])
    if reporting < 0 or reporting > 100:
        raise ValueError("%s reports an impossible percentage: %s" % (name, reporting))
    votes = entry["votes"]
    if not votes:
        raise ValueError("%s lists no candidates" % name)
    return name, reporting, votes


def anchor_welcome(network, district_count):
    print("Good evening, and welcome to %s election night coverage." % network)
    print("We are tracking returns from %d districts tonight." % district_count)


def polls_closed_announcement():
    print("The polls have officially closed and the counting is under way.")


def report_district(name, reporting, votes):
    leader, margin = leader_and_margin(votes)
    print("%s -- %.1f%% of precincts reporting." % (name, reporting))
    print("  Current leader: %s" % leader)
    print("  Vote margin: %d votes" % margin)
    print("  Estimated uncounted ballots: %d" % remaining_ballots(votes, reporting))
    if reporting == 100:
        print("  Projected winner in %s: %s" % (name, leader))
        return leader
    return None


def sign_off(projections):
    if projections:
        print("Tonight we projected winners in %d of our districts." % len(projections))
    else:
        print("No district is final yet, so we have no projections to share.")
    print("That is all from the decision desk -- thank you for watching.")


def credits_roll(network):
    print("Produced by the %s politics unit." % network)
    print("-- credits roll --")


def broadcast(districts):
    network = "the National Network"
    anchor_welcome(network, len(districts))
    polls_closed_announcement()
    projections = []
    for index, entry in enumerate(districts, start=1):
        name, reporting, votes = validate_district(entry, index)
        winner = report_district(name, reporting, votes)
        if winner is not None:
            projections.append((name, winner))
    sign_off(projections)
    credits_roll(network)
    return projections


def main():
    results = [
        {"name": "Riverside", "reporting": 100, "votes": {"Alvarez": 48210, "Boone": 41775}},
        {"name": "Fairhaven", "reporting": 62.5, "votes": {"Chen": 20140, "Duval": 19980}},
        {"name": "Northgate", "reporting": 100, "votes": {"Ellis": 30500, "Farouk": 30490}},
    ]
    broadcast(results)


if __name__ == "__main__":
    main()

