HELM_ORDERS = {
    "tack": "Helm down! Bring the bow through the wind.",
    "jibe": "Helm up! Swing the stern through the wind.",
    "head up": "Helm to windward, ease her closer to the breeze.",
    "bear away": "Helm to leeward, let her fall off the wind.",
}

WIND_SIDES = {
    "tack": "port",
    "jibe": "starboard",
    "head up": "port",
    "bear away": "starboard",
}


def normalize(maneuver):
    if not isinstance(maneuver, str):
        raise TypeError("maneuvers must be strings, got %r" % (maneuver,))
    name = " ".join(maneuver.lower().split())
    if name not in HELM_ORDERS:
        raise ValueError("unknown maneuver: %r" % (maneuver,))
    return name


def weigh_anchor():
    print("Weighing anchor: chain rattling through the hawsehole.")
    print("Anchor is aweigh and secured at the bow roller.")


def hoist_mainsail():
    print("Hoisting the mainsail: halyard taut, battens clear.")
    print("Mainsail is up and drawing nicely.")


def adjust_helm(name):
    print("Helm adjustment -> %s" % HELM_ORDERS[name])


def check_wind(name):
    print("Wind check -> breeze on the %s side, telltales streaming." % WIND_SIDES[name])


def position_crew(name):
    print("Crew positioning -> hands to the %s rail, sheets in hand for the %s."
          % (WIND_SIDES[name], name))


def warn_boom():
    print("DUCK UNDER THE BOOM! JIBE-HO!")


def dock():
    print("Docking approach: sails furled, engine idling, fenders over the side.")
    print("Tying the mooring lines: bow line, stern line, and two springs made fast.")


def sail(maneuvers):
    if not isinstance(maneuvers, (list, tuple)):
        raise TypeError("maneuvers must be a list of directional changes.")
    plan = [normalize(m) for m in maneuvers]
    weigh_anchor()
    hoist_mainsail()
    for step, name in enumerate(plan, 1):
        print("--- Maneuver %d of %d: %s ---" % (step, len(plan), name))
        adjust_helm(name)
        check_wind(name)
        position_crew(name)
        if name == "jibe":
            warn_boom()
    dock()
    return len(plan)


def main():
    voyage = ["tack", "Head Up", "jibe", "bear away", "tack"]
    completed = sail(voyage)
    print("Voyage complete after %d maneuvers." % completed)


if __name__ == "__main__":
    main()

