text_nat:
def call_to_order():
    print("BAILIFF: All rise! Court is now in session.")
    print("BAILIFF: The Honorable Judge Marlowe presiding.")
    print("JUDGE: Be seated. Let the record show the court has entered.")


def normalize(witness):
    if isinstance(witness, dict):
        name = witness.get("name")
        expert = bool(witness.get("expert"))
        credentials = witness.get("credentials") or []
    else:
        name = witness
        expert = False
        credentials = []
    if not name:
        raise ValueError("every witness must have a name")
    if isinstance(credentials, str):
        credentials = [credentials]
    return {"name": name, "expert": expert, "credentials": list(credentials)}


def swear_in(name):
    print("CLERK: %s, please raise your right hand." % name)
    print("CLERK: Do you swear to tell the truth, the whole truth,")
    print("       and nothing but the truth?")
    print("%s: I do." % name.upper())


def read_credentials(name, credentials):
    print("JUDGE: The witness is offered as an expert. Read the credentials.")
    if credentials:
        for index, item in enumerate(credentials, 1):
            print("CLERK: (%d) %s" % (index, item))
    else:
        print("CLERK: The record contains no filed credentials for %s." % name)
    print("JUDGE: The court accepts %s as an expert witness." % name)


def direct_examination(name):
    print("COUNSEL FOR THE PLAINTIFF: Direct examination of %s." % name)
    print("COUNSEL FOR THE PLAINTIFF: State what you observed that evening.")
    print("%s: I answer to the best of my recollection." % name.upper())
    print("COUNSEL FOR THE PLAINTIFF: No further questions on direct.")


def cross_examination(name):
    print("COUNSEL FOR THE DEFENSE: Cross examination of %s." % name)
    print("COUNSEL FOR THE DEFENSE: Isn't it true your view was obstructed?")
    print("%s: I stand by my statement." % name.upper())
    print("JUDGE: The witness may step down.")


def dismiss_jury(count):
    print("JUDGE: The jury has heard %d witness(es)." % count)
    print("JUDGE: Members of the jury, you are dismissed to deliberate.")
    print("JUDGE: This session is adjourned. *gavel strike*")


def litigate(witnesses):
    call_to_order()
    heard = 0
    for witness in witnesses:
        person = normalize(witness)
        name = person["name"]
        print("BAILIFF: Calling %s to the stand." % name)
        swear_in(name)
        if person["expert"]:
            read_credentials(name, person["credentials"])
        direct_examination(name)
        cross_examination(name)
        heard += 1
    dismiss_jury(heard)


def main():
    roster = [
        "Harold Finch",
        {"name": "Dr. Amina Sowell", "expert": True,
         "credentials": ["PhD in forensic pathology",
                         "Twenty years with the state medical examiner"]},
        {"name": "Ruth Delgado", "expert": False},
    ]
    litigate(roster)


if __name__ == "__main__":
    main()

