def _pins_at(rolls, index):
    if index < len(rolls):
        return rolls[index]
    return 0


def _validate(rolls):
    if not isinstance(rolls, (list, tuple)):
        raise TypeError("rolls must be a list of integers")
    for pins in rolls:
        if not isinstance(pins, int):
            raise ValueError("each roll must be an integer, got %r" % (pins,))
        if pins < 0 or pins > 10:
            raise ValueError("each roll must knock down 0 to 10 pins, got %d" % pins)


def score(rolls):
    _validate(rolls)
    print("Welcome to the bowling alley!")
    total = 0
    index = 0
    frames_played = 0
    for frame in range(1, 11):
        if index >= len(rolls):
            break
        frames_played = frame
        first = rolls[index]
        print("Frame %d, roll 1: %d pin(s)" % (frame, first))
        if first == 10:
            print("Strike!")
            total += 10 + _pins_at(rolls, index + 1) + _pins_at(rolls, index + 2)
            index += 1
        else:
            second = _pins_at(rolls, index + 1)
            print("Frame %d, roll 2: %d pin(s)" % (frame, second))
            if first + second > 10:
                raise ValueError("frame %d knocks down more than 10 pins" % frame)
            if first + second == 10:
                print("Spare!")
                total += 10 + _pins_at(rolls, index + 2)
            else:
                print("Open frame.")
                total += first + second
            index += 2
        print("Running total after frame %d: %d" % (frame, total))
        if frame == 10:
            for bonus in rolls[index:]:
                print("Bonus roll: %d pin(s)" % bonus)
    if frames_played < 10:
        print("Game incomplete: only %d frame(s) were bowled." % frames_played)
    print("Final score: %d" % total)
    if total == 300:
        print("PERFECT GAME! A glorious three hundred!")
    return total


def summarize(label, rolls):
    print("=== %s ===" % label)
    result = score(rolls)
    print("%s scored %d point(s) from %d roll(s)." % (label, result, len(rolls)))
    return result


if __name__ == "__main__":
    summarize("Sample game", [10, 7, 3, 9, 0])
    print("-" * 34)
    summarize("Turkey parade", [10] * 12)
    print("-" * 34)
    summarize("Spare city", [5, 5] * 10 + [5])

