def validate(readings):
    clean = []
    for entry in readings:
        if len(entry) != 3:
            print("Skipping malformed reading: %s" % (entry,))
            continue
        day, temp, gravity = entry
        clean.append((int(day), float(temp), float(gravity)))
    clean.sort()
    return clean


def temperature_alerts(day, temp):
    if temp > 25:
        print("Day %d: COOLING SYSTEM ALERT - tank at %.1fC" % (day, temp))
    if temp < 18:
        print("Day %d: HEATING SYSTEM ALERT - tank at %.1fC" % (day, temp))


def attenuation(original, current):
    if original <= 1.0:
        return 0.0
    return (original - current) / (original - 1.0) * 100.0


def abv(original, current):
    return (original - current) * 131.25


def schedule_events(day):
    if day == 5:
        print("Day 5: adding dry hops to the fermenter")
    if day == 10:
        print("Day 10: starting cold crash to drop the yeast")


def brew(readings):
    log = validate(readings)
    print("=== Fermentation Log ===")
    if not log:
        print("No valid readings recorded; nothing to report")
        return
    original = log[0][2]
    print("Original gravity recorded as %.3f" % original)
    for day, temp, gravity in log:
        print("--- Day %d ---" % day)
        print("Temperature: %.1fC | Gravity: %.3f" % (temp, gravity))
        print("Apparent attenuation: %.1f%%" % attenuation(original, gravity))
        temperature_alerts(day, temp)
        if gravity < 1.01:
            print("Day %d: fermentation is nearly complete" % day)
        schedule_events(day)
    final = log[-1][2]
    print("=== Summary ===")
    print("Days monitored: %d" % len(log))
    print("Final gravity: %.3f" % final)
    print("Estimated ABV: %.2f%%" % abv(original, final))
    print("Batch is ready for packaging")


def main():
    sample = [(1, 20, 1.050), (5, 26, 1.020)]
    brew(sample)
    print("")
    extended = [(1, 19, 1.060), (3, 17, 1.040), (5, 26, 1.022),
                (7, 21, 1.008), (10, 19, 1.006)]
    brew(extended)


if __name__ == "__main__":
    main()

