def validate_cue(cue):
    if len(cue) != 4:
        raise ValueError("each cue needs scene, area, color, intensity")
    scene, area, color, intensity = cue
    if not isinstance(scene, int) or scene < 1:
        raise ValueError("scene number must be a positive integer")
    if intensity < 0 or intensity > 100:
        raise ValueError("intensity must be a percentage between 0 and 100")
    return scene, str(area), str(color).lower(), intensity


def describe_level(intensity):
    if intensity == 0:
        return "dark"
    if intensity < 40:
        return "low"
    if intensity < 80:
        return "mid"
    return "full"


def standby(scene, area):
    print("STANDBY: scene %d, %s" % (scene, area))


def go(scene):
    print("GO: lighting desk executes cue for scene %d" % scene)


def run_cue(cue):
    scene, area, color, intensity = validate_cue(cue)
    standby(scene, area)
    go(scene)
    if intensity == 0:
        print("BLACKOUT: all channels down in %s" % area)
    if color == "red":
        print("WARNING: special effects lighting (red) in use")
    print("Illuminating %s in %s at %d%% (%s)" % (area, color, intensity, describe_level(intensity)))
    if scene == 5:
        print("INTERMISSION: house lights up after scene 5")
    return scene, intensity


def summarize(records):
    if not records:
        print("No cues were run tonight.")
        return
    scenes = len(records)
    blackouts = 0
    total = 0
    for scene, intensity in records:
        total = total + intensity
        if intensity == 0:
            blackouts = blackouts + 1
    print("Cues run: %d" % scenes)
    print("Blackouts: %d" % blackouts)
    print("Average intensity: %.1f%%" % (float(total) / scenes))


def illuminate(cues):
    print("The performance begins: house to half, stage crew standing by.")
    records = []
    for cue in cues:
        records.append(run_cue(cue))
    print("CURTAIN CALL: bring up the warm wash and take the bows.")
    summarize(records)
    return records


def main():
    illuminate([(1, "stage left", "blue", 80),
                (3, "apron", "red", 55),
                (5, "center", "white", 0)])


if __name__ == "__main__":
    main()

