def format_position(coord, altitude):
    return "%s at %d feet" % (coord, altitude)


def validate(waypoints):
    checked = []
    for entry in waypoints:
        if len(entry) != 3:
            raise ValueError("each waypoint needs coordinate, altitude and action")
        coord, altitude, action = entry
        if altitude < 0:
            raise ValueError("altitude cannot be negative at %s" % coord)
        checked.append((coord, int(altitude), action.lower()))
    return checked


def startup():
    print("Engine startup sequence initiated.")
    print("Rotors engaged, blades at full RPM.")
    print("Lifting off for search and rescue mission.")


def perform_search(coord, altitude):
    print("Scanning %s with searchlight and thermal camera." % format_position(coord, altitude))


def perform_hover(coord, altitude):
    print("Holding altitude at %d feet over %s." % (altitude, coord))


def perform_deploy(coord, altitude):
    print("Lowering the rescue basket to the ground at %s." % coord)
    print("Winch operator paying out cable from %d feet." % altitude)


def perform_extract(coord):
    print("Patient is onboard and secured, leaving %s." % coord)


def handle_action(coord, altitude, action):
    if action == "search":
        perform_search(coord, altitude)
    elif action == "hover":
        perform_hover(coord, altitude)
    elif action == "deploy":
        perform_deploy(coord, altitude)
    elif action == "extract":
        perform_extract(coord)
    else:
        print("Unknown action '%s' at %s, continuing flight." % (action, coord))


def rescue(waypoints):
    legs = validate(waypoints)
    startup()
    patients = 0
    for coord, altitude, action in legs:
        print("Arrived at %s." % format_position(coord, altitude))
        handle_action(coord, altitude, action)
        if action == "extract":
            patients += 1
    print("Mission complete, returning to base.")
    if patients:
        print("Carrying %d rescued patient(s) to the medical pad." % patients)
    print("Touchdown at base, landing gear stable.")
    print("Engine shutdown, rotors winding down.")
    return patients


def main():
    flight = [("North Ridge", 5000, "search"),
              ("Canyon Mouth", 4200, "hover"),
              ("Canyon Floor", 800, "deploy"),
              ("River", 3000, "extract")]
    rescued = rescue(flight)
    print("Flight log closed with %d rescue(s)." % rescued)


if __name__ == "__main__":
    main()

