text_nat:
def light_forge():
    print("The coal forge is lit; smoke curls up and the bellows breathe.")
    return {"hot": False, "blows": 0, "bends": 0, "quenches": 0}


def heat(state):
    state["hot"] = True
    print("The metal rests in the coals and glows a deep orange.")


def hammer(state):
    state["blows"] += 1
    if state["hot"]:
        print("CLANG! The anvil rings as the hammer falls on soft metal.")
    else:
        print("Clank... the cold metal barely moves under the hammer.")


def bend(state):
    state["bends"] += 1
    print("The billet is drawn over the horn and a smooth curve takes shape.")


def quench(state):
    state["quenches"] += 1
    state["hot"] = False
    print("TSSSSSS! The blade plunges into the slack tub and steam rises.")


def unknown(action):
    print("Error: the smith does not know how to '%s'." % action)


def inspect_blade(state):
    print("The smith lifts the finished blade to the light and inspects it.")
    print("Hammer blows: %d, bends: %d, quenches: %d" % (
        state["blows"], state["bends"], state["quenches"]))
    if state["blows"] == 0:
        print("The bar is untouched; this is no blade at all.")
    elif state["quenches"] == 0:
        print("The steel is shaped but soft, still waiting for its quench.")
    else:
        print("The edge is true and the temper looks sound.")


def bank_fire():
    print("Water is poured over the coals and the forge fire is quenched.")


def forge(actions):
    if not isinstance(actions, list):
        print("Error: the action list must be a list of strings.")
        return None
    state = light_forge()
    handlers = {"heat": heat, "hammer": hammer, "bend": bend, "quench": quench}
    for action in actions:
        if not isinstance(action, str):
            unknown(repr(action))
            continue
        key = action.strip().lower()
        if key in handlers:
            handlers[key](state)
        else:
