def calibrate(press_name):
    print("=== %s calibration sequence ===" % press_name)
    print("Warming rollers to 180 C")
    print("Zeroing registration marks")
    return {"pages": 0, "jams": 0}


def validate(batch):
    color, pages, speed = batch
    if not isinstance(pages, int) or pages <= 0:
        print("Rejected %s: page count must be a positive integer" % color)
        return False
    if speed not in ("fast", "slow"):
        print("Rejected %s: unknown speed setting '%s'" % (color, speed))
        return False
    return True


def load_ink(color, pages):
    print("Loading %s ink cartridge" % color)
    print("Feeding %d sheets into the tray" % pages)


def apply_speed(speed):
    if speed == "fast":
        print("WARNING: noise levels above 85 dB, wear ear protection")
    else:
        print("Engaging precision alignment for slow feed")


def run_batch(batch, stats):
    color, pages, speed = batch
    load_ink(color, pages)
    apply_speed(speed)
    halfway = pages // 2
    print("Progress: %d of %d pages printed (50%%)" % (halfway, pages))
    stats["pages"] += pages
    if pages > 10000:
        stats["jams"] += 1
        print("ERROR: paper jam detected in %s batch at sheet %d" % (color, 10000))
        print("Batch %s aborted after jam recovery" % color)
        return False
    print("Batch %s completed: %d pages" % (color, pages))
    return True


def shutdown(stats):
    print("Flushing residual ink from all channels")
    print("Total pages processed: %d" % stats["pages"])
    if stats["jams"]:
        print("Maintenance required: %d jam(s) logged" % stats["jams"])
    else:
        print("No jams logged, press is clean")
    print("Press shutdown complete")


def printrun(batches):
    stats = calibrate("Heidelberg X9")
    for batch in batches:
        if not validate(batch):
            continue
        run_batch(batch, stats)
    shutdown(stats)
    return stats


def main():
