def validate(triggers):
    if not isinstance(triggers, list):
        raise TypeError("triggers must be a list of (time, animal, temperature) tuples")
    clean = []
    for item in triggers:
        if len(item) != 3:
            raise ValueError("each trigger needs exactly three fields")
        time_stamp, animal, temperature = item
        clean.append((str(time_stamp), str(animal).lower(), int(temperature)))
    return clean


def initialize():
    print("Camera module CT-7 initializing...")
    print("Infrared sensor armed, lens cover retracted.")


def classify(animal):
    if animal == "bear":
        print("ALERT: large mammal in frame - maintaining distance protocol")
        return "large mammal"
    if animal == "bird":
        print("Bird detected - ignoring, too small for the survey")
        return "ignored"
    print("Logging %s as a standard sighting" % animal)
    return "standard"


def check_battery(temperature):
    if temperature < 32:
        print("WARNING: battery efficiency reduced at %d degrees" % temperature)
        return True
    return False


def capture_burst(time_stamp):
    for shot in range(1, 4):
        print("Captured photo %d of 3 at %s" % (shot, time_stamp))


def report(sightings, ignored, cold_events):
    print("--- End of log ---")
    print("Total sightings recorded: %d" % sightings)
    if ignored:
        print("Triggers discarded as birds: %d" % ignored)
    if cold_events:
        print("Sub-freezing triggers logged: %d" % cold_events)


def monitor(triggers):
    events = validate(triggers)
    initialize()
    sightings = 0
    ignored = 0
    cold_events = 0
    for index, event in enumerate(events, 1):
        time_stamp, animal, temperature = event
        print("[%s] Movement detected by the motion sensor" % time_stamp)
        kind = classify(animal)
        if kind == "ignored":
            ignored += 1
        else:
            sightings += 1
        if check_battery(temperature):
            cold_events += 1
        capture_burst(time_stamp)
        if index == 11:
            print("ALERT: memory card full - overwriting oldest frames")
    report(sightings, ignored, cold_events)
    return sightings


if __name__ == "__main__":
    total = monitor([("02:00", "bear", 30), ("14:00", "bird", 45)])
    print("Survey returned %d usable sighting(s)" % total)

