def announce_first_whistle(jam_count):
    print("The referee raises the whistle to open the first half.")
    print("Two short blasts -- %d jams are on the card tonight." % jam_count)


def announce_sprint(number, jammer, team):
    print("Jam %d: %s of the %s sprints off the starting line." % (number, jammer, team))


def announce_defense(team):
    print("Zero on the board -- the pack throws a strong defensive block at the %s jammer." % team)


def announce_passes(jammer, points):
    if points == 1:
        print("%s slips past a single opponent for 1 point." % jammer)
    else:
        print("%s carves through the pack and passes %d opponents." % (jammer, points))


def announce_track_cut(jammer, penalty):
    print("Whistle and a hand signal: %s is called for a track cut violation." % jammer)
    print("%s takes a trip to the penalty box, costing %d points." % (jammer, penalty))


def announce_lead(jammer, points):
    if points > 0:
        print("Lead jammer status: %s holds the lead and calls off the jam." % jammer)
    else:
        print("Lead jammer status: no lead jammer awarded on that pass.")


def score_jam(scores, team, points):
    scores[team] = scores.get(team, 0) + points
    return scores[team]


def format_scoreboard(scores):
    parts = []
    for team in sorted(scores):
        parts.append("%s %d" % (team, scores[team]))
    return " -- ".join(parts)


def announce_halftime(scores):
    print("Halftime! The skaters roll to the benches for water and tape.")
    print("Score at the break: %s" % format_scoreboard(scores))


def announce_final(scores):
    print("Final score: %s" % format_scoreboard(scores))
    ranked = sorted(scores.items(), key=lambda pair: -pair[1])
    if len(ranked) > 1 and ranked[0][1] == ranked[1][1]:
        print("It ends level -- both benches share the night.")
    else:
        print("The %s take the bout!" % ranked[0][0])
    print("Skaters skate out to the crowd for high fives. Good night, derby fans!")


def derby(jams):
    announce_first_whistle(len(jams))
    scores = {}
    halfway = len(jams) // 2
    for index, jam in enumerate(jams):
        jammer, team, points = jam
        if index == halfway and halfway > 0:
            announce_halftime(scores)
        announce_sprint(index + 1, jammer, team)
        if points == 0:
            announce_defense(team)
        elif points > 0:
            announce_passes(jammer, points)
        else:
            announce_track_cut(jammer, -points)
        announce_lead(jammer, points)
        print("%s now sits on %d points." % (team, score_jam(scores, team, points)))
    announce_final(scores)


def main():
    derby([("Smash", "Rockets", 4), ("Dash", "Comets", 0),
           ("Bolt", "Rockets", -2), ("Vex", "Comets", 3)])


if __name__ == "__main__":
    main()

