def validate(catches):
    clean = []
    for entry in catches:
        if len(entry) != 3:
            raise ValueError("each catch needs angler, species, weight")
        angler, species, weight = entry
        clean.append((str(angler), str(species).lower(), float(weight)))
    return clean


def drill_holes(anglers):
    print("Brrrrrrrap! The augers bite into the ice.")
    for angler in anglers:
        print("%s drills a fresh hole and drops a line." % angler)
    print("%d holes steam in the cold air." % len(anglers))


def report_catch(angler, species, weight):
    print("%s sets the hook -- a %s is on!" % (angler, species))
    if species == "walleye":
        print("That's a keeper, %s! Walleye in the bucket." % angler)
    if species == "perch":
        print("Just a little small fry perch, toss it back or fry it up.")
    if weight > 5:
        print("TROPHY ALERT: %.1f pounds on the ice!" % weight)
    if weight > 10:
        print("SNAP! The line broke under %.1f pounds of fish." % weight)
        return 0.0
    return weight


def weigh_in(totals):
    print("The weigh-in scales are swinging on the judges' tent.")
    for angler in sorted(totals):
        print("%s weighs in at %.1f pounds." % (angler, totals[angler]))


def find_winner(totals):
    best = None
    for angler in sorted(totals):
        if best is None or totals[angler] > totals[best]:
            best = angler
    return best


def fish(catches):
    entries = validate(catches)
    anglers = []
    for angler, species, weight in entries:
        if angler not in anglers:
            anglers.append(angler)
    drill_holes(anglers)
    totals = {}
    for angler in anglers:
        totals[angler] = 0.0
    for angler, species, weight in entries:
        totals[angler] += report_catch(angler, species, weight)
    weigh_in(totals)
    print("WHEEEEEE! The final siren echoes across the frozen lake.")
    winner = find_winner(totals)
    if winner is None:
        print("No fish were landed today, so nobody takes the trophy.")
    else:
        print("The winner is %s with %.1f pounds!" % (winner, totals[winner]))
    return totals


def main():
    results = fish([("Bob", "walleye", 6), ("Alice", "perch", 1)])
    print("Official card: %d anglers recorded." % len(results))


if __name__ == "__main__":
    main()

