def validate(stages):
    checked = []
    for entry in stages:
        if len(entry) != 3:
            raise ValueError("each stage needs system, status and temperature")
        system, status, temperature = entry
        checked.append((str(system), str(status).lower(), int(temperature)))
    return checked


def activate_stage(system, status, temperature):
    print("Activating system: %s" % system)
    if status == "nominal":
        print("  Green light confirmed on %s." % system)
    elif status == "alert":
        print("  ALERT: manual override engaged on %s." % system)
    else:
        print("  Unknown status '%s' reported by %s; holding stage." % (status, system))
    if temperature > 300:
        print("  WARNING: %d C exceeds limit, inserting control rods." % temperature)
    return temperature


def coolant_loop(peak):
    print("Primary coolant loop activated.")
    print("Loop pressure trimmed for peak reading of %d C." % peak)


