    authorize("Kowalski")
    checked = validate(stages)
    if not checked:
        print("No stages queued; startup aborted.")
        return 0
    peak = 0
    for system, status, temperature in checked:
        reading = activate_stage(system, status, temperature)
        if reading > peak:
            peak = reading
    coolant_loop(peak)
    turbine()
