def format_altitude(meters):
    return "%d m (%.0f ft)" % (meters, meters * 3.28084)


def validate_camps(camps):
    checked = []
    for entry in camps:
        if len(entry) != 3:
            raise ValueError("each camp needs a name, an altitude and a weather report")
        name, altitude, weather = entry
        if altitude <= 0:
            raise ValueError("altitude of %s must be positive" % name)
        checked.append((name, int(altitude), str(weather).lower()))
    return checked


def report_weather(name, weather):
    if weather == "clear":
        print("Radio from %s: skies are clear, visibility is excellent." % name)
        return True
    if weather == "blizzard":
        print("Blizzard hammering %s: all climbers into the tents, lockdown until it passes." % name)
        return False
    print("Weather at %s is reported as '%s' - staying alert." % (name, weather))
    return True


def death_zone_check(name, altitude):
    if altitude > 8000:
        print("DEATH ZONE at %s: the body is dying above 8000 m." % name)
        print("Oxygen masks are mandatory from here on.")
        return True
    return False


def ascend(camps):
    route = validate_camps(camps)
    print("Base camp: prayer flags snapping, loads roped, the team departs.")
    highest = 0
    windows = 0
    for name, altitude, weather in route:
        print("Arrived at %s, altitude %s." % (name, format_altitude(altitude)))
        death_zone_check(name, altitude)
        if report_weather(name, weather):
            windows = windows + 1
        print("Hydration reminder: melt snow and drink, dehydration comes before frostbite.")
        if altitude > highest:
            highest = altitude
    print("Highest camp reached: %s." % format_altitude(highest))
    print("Good-weather windows logged: %d of %d camps." % (windows, len(route)))
    print("Summit push: 2 a.m. start, headlamps on, crampons biting the ice.")
    print("Summit reached - flag unfurled, photograph taken at the top of the world.")
    print("Descent begins immediately; the mountain is only half climbed at the summit.")
    return highest


def main():
    route = [
        ("Camp 1", 5000, "clear"),
        ("Camp 2", 6400, "snow"),
        ("Camp 3", 7200, "clear"),
        ("Camp 4", 8200, "blizzard"),
    ]
    summit = ascend(route)
    print("Expedition log closed at %s." % format_altitude(summit))


if __name__ == "__main__":
    main()

