def equipment_check():
    print("Morning equipment check: inspecting hoses, ladders and air tanks.")
    print("All gear stowed on Engine 12 and signed off by the captain.")


def sound_alarm(address):
    print("Station alarm sounding! Call received from %s." % address)
    print("Firefighters sliding down the pole.")
    print("Crew boarding the truck and rolling out.")


def deploy_medical_gear():
    print("Deploying the oxygen kit and trauma bag.")


def connect_hoses():
    print("Connecting the hoses to the nearest hydrant.")


def request_backup(address):
    print("Requesting backup units to %s -- severity is high." % address)


def handle_emergency(emergency, address):
    if emergency == "medical":
        deploy_medical_gear()
    elif emergency == "fire":
        connect_hoses()
    else:
        print("Assessing an unusual emergency type: %s." % emergency)


def clear_scene(address):
    print("Scene at %s is clear, rolling up equipment." % address)


def return_to_quarters():
    print("Returning to quarters and restocking the truck.")


def validate_call(call):
    if len(call) != 3:
        raise ValueError("each call needs address, emergency type and severity")
    address, emergency, severity = call
    return address, emergency.lower(), severity.lower()


def summarize(counts):
    print("Shift summary:")
    for emergency in sorted(counts):
        print("  %s calls: %d" % (emergency, counts[emergency]))


def dispatch(calls):
    equipment_check()
    counts = {}
    for call in calls:
        address, emergency, severity = validate_call(call)
        sound_alarm(address)
        handle_emergency(emergency, address)
        if severity == "high":
            request_backup(address)
        clear_scene(address)
        return_to_quarters()
        counts[emergency] = counts.get(emergency, 0) + 1
    summarize(counts)
    return counts


def main():
    shift = [("Main St", "medical", "low"), ("Oak Ave", "fire", "high")]
    totals = dispatch(shift)
    print("Total calls answered: %d" % sum(totals.values()))


