def classify(item):
    """Return the handling category for a single material type."""
    name = str(item).strip().lower()
    if name in ('heavy', 'steel', 'machinery', 'container'):
        return 'heavy'
    if name in ('fragile', 'glass', 'ceramics', 'electronics'):
        return 'fragile'
    if name in ('liquid', 'oil', 'water', 'fuel'):
        return 'liquid'
    return 'standard'


def announce(category, item):
    """Emit the notification that matches the item's category."""
    if category == 'heavy':
        print("Crane warning: '%s' is heavy, use the gantry crane!" % item)
    elif category == 'fragile':
        print("Handle '%s' with care, it is fragile." % item)
    elif category == 'liquid':
        print("Check for spills before stowing the liquid '%s'." % item)
    else:
        print("Loaded '%s' into the hold." % item)


def load(items):
    """Load every material type in items and report the voyage status."""
    print("Welcome to the Port of Rotterdam, loading begins now.")
    if not isinstance(items, (list, tuple)):
        raise TypeError('load() expects a list of material types')

    loaded = 0
    for item in items:
        announce(classify(item), item)
        loaded += 1

    print("HOOOOONK! The ship's horn sounds across the harbour.")
    print("Total items loaded: %d" % loaded)
    print("All cargo secured, the voyage departs on schedule.")
    return loaded


def main():
    first = load(['heavy', 'fragile', 'normal'])
    print("Manifest one closed with %d unit(s)." % first)

    second = load(['steel', 'glass', 'oil', 'rope', 'machinery'])
    print("Manifest two closed with %d unit(s)." % second)
    print("Port total for today: %d unit(s)." % (first + second))


if __name__ == '__main__':
    main()

