import time


def parse_steps(text):
    """Turn a comma separated stage description into a list of numbers."""
    steps = []
    for chunk in text.split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        steps.append(int(chunk))
    return steps


def baud_rate(stage_index):
    """Negotiated speed drops as the modem works through later stages."""
    rates = [56000, 33600, 28800, 14400, 9600, 2400]
    return rates[stage_index % len(rates)]


def noise_level(stage_index, step):
    """A reproducible pseudo measurement in decibels."""
    return -((stage_index * 7 + step * 13) % 40) - 20


def assigned_address(steps):
    """Derive a fake dynamic IP from the stage list."""
    total = sum(steps)
    return "192.168.%d.%d" % (total % 256, (total * 3 + 11) % 256)


def session_timestamp():
    return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())


def connect(steps):
    print("ATDT 555-0134 ... dial tone detected")
    for index, step in enumerate(steps):
        if step == 1:
            print("[stage %d] handshake started with remote host" % index)
        elif step == 2:
            print("[stage %d] negotiating baud rate: %d bps" % (index, baud_rate(index)))
        elif step == 3:
            print("[stage %d] line noise level: %d dB" % (index, noise_level(index, step)))
        else:
            print("[stage %d] verifying password (attempt %d)" % (index, step))
    print("=== CONNECT %d -- connection established ===" % baud_rate(len(steps)))
    print("Your address is %s" % assigned_address(steps))
    print("Session started at %s" % session_timestamp())


def main():
    description = "1, 3, 9"
    steps = parse_steps(description)
    print("Loading dial plan: %s" % description)
    connect(steps)
    print("Stages processed: %d" % len(steps))


if __name__ == "__main__":
    main()

