LASER_DAMAGE = 12
MELEE_DAMAGE = 9
SHIELD_DAMAGE = 0
DODGE_DAMAGE = 2

LASER_MOVES = ('laser', 'beam', 'blaster')
MELEE_MOVES = ('melee', 'sword', 'punch', 'kick')
SHIELD_MOVES = ('shield', 'guard', 'block')


def classify(move):
    name = str(move).strip().lower()
    if name in LASER_MOVES:
        return 'laser'
    if name in MELEE_MOVES:
        return 'melee'
    if name in SHIELD_MOVES:
        return 'shield'
    return 'dodge'


def damage_of(category):
    table = {
        'laser': LASER_DAMAGE,
        'melee': MELEE_DAMAGE,
        'shield': SHIELD_DAMAGE,
        'dodge': DODGE_DAMAGE,
    }
    return table[category]


def perform(move, category):
    if category == 'laser':
        print("The %s hums and charges: zzzzzt-VWOOOM!" % move)
    elif category == 'melee':
        print("The %s swings through the air: whoosh-CLANG!" % move)
    elif category == 'shield':
        print("The %s snaps up and holds: block confirmed!" % move)
    else:
        print("Rolling aside with a %s, the fighter dodges low and fast." % move)


def fight(moves):
    print("Welcome to the Iron Arena, where steel and light decide the day!")
    print("Tonight's challenger brings %d move(s) into the ring." % len(moves))
    total = 0
    for index, move in enumerate(moves, 1):
        category = classify(move)
        print("Move %d of %d: %s" % (index, len(moves), move))
        perform(move, category)
        total = total + damage_of(category)
