def validate_bids(bids):
    clean = []
    for raw in bids:
        try:
            value = float(raw)
        except (TypeError, ValueError):
            print("Ignoring unreadable offer: %r" % (raw,))
            continue
        if value <= 0:
            print("Ignoring non-positive offer: %s" % format_money(value))
            continue
        clean.append(value)
    return clean


def classify(bid):
    if bid < 50:
        return "rejected"
    if bid <= 90:
        return "once"
    if bid == 100:
        return "twice"
    return "gasp"


def announce(bid):
    kind = classify(bid)
    if kind == "rejected":
        print("Bid rejected! %s is below the reserve." % format_money(bid))
    elif kind == "once":
        print("Going once at %s..." % format_money(bid))
    elif kind == "twice":
        print("Going twice at %s..." % format_money(bid))
    else:
        print("*The crowd gasps* %s on the floor!" % format_money(bid))
    return kind


def winning_paddle(bids):
    best = 0
    paddle = 0
    for index, bid in enumerate(bids):
        if bid > best:
            best = bid
            paddle = index + 1
