    if reading < 10:
        return "all-clear"
    if reading <= 20:
        return "tremor"
    if reading > 50:
        return "evacuation"
    return "magma"


def describe(reading, category):
    if category == "all-clear":
        return "Reading %.1f: all clear, seismic background noise only." % reading
    if category == "tremor":
        return "Reading %.1f: TREMOR WARNING, minor ground motion detected." % reading
    if category == "evacuation":
        return "Reading %.1f: EVACUATION ORDER, structural failure imminent." % reading
    return "Reading %.1f: magma level observation, chamber pressure rising." % reading


def validate(readings):
    clean = []
    for item in readings:
        try:
            clean.append(float(item))
        except (TypeError, ValueError):
            print("Discarding non-numeric reading: %r" % (item,))
    return clean


def trajectory(readings):
    if not readings:
        return "no particulate data available"
    peak = max(readings)
    drift = peak * 1.5
    return "plume drifting %.1f km downwind from peak reading %.1f" % (drift, peak)


def assessment(counts):
    if counts.get("evacuation"):
        return "CRITICAL: evacuation zones must remain sealed."
    if counts.get("magma"):
        return "ELEVATED: magma movement requires continuous watch."
    if counts.get("tremor"):
        return "GUARDED: tremors logged, crews on standby."
    return "NORMAL: no significant activity recorded."


def monitor(readings):
    print("Seismic monitoring array online: all sensors calibrated.")
    values = validate(readings)
    counts = {}
    for reading in values:
        category = classify(reading)
        counts[category] = counts.get(category, 0) + 1
        print(describe(reading, category))
