def classify(code):
    if isinstance(code, bool) or not isinstance(code, (int, float)):
        return "anomaly"
    if code < 0:
        return "past"
    if code > 0:
        return "future"
    return "present"


def describe(code):
    if isinstance(code, float):
        return "%.1f years" % abs(code)
    return "%d years" % abs(code)


def scan_report(jumps):
    eras = {}
    for code in jumps:
        kind = classify(code)
        eras[kind] = eras.get(kind, 0) + 1
    parts = []
    for kind in ("past", "present", "future", "anomaly"):
        if kind in eras:
            parts.append("%s=%d" % (kind, eras[kind]))
    return ", ".join(parts)


def paradox_level(jumps):
    risk = 0
    for code in jumps:
        if classify(code) in ("past", "anomaly"):
            risk += 1
    if risk == 0:
        return "STABLE"
    if risk < 3:
        return "CAUTION"
    return "CRITICAL"


def travel(coordinates):
    print("Flux capacitor charging... 1.21 gigawatts online.")
    print("Destination codes loaded: %d" % len(coordinates))
    for code in coordinates:
        kind = classify(code)
        if kind == "past":
            print("Arrival alert: past era, %s behind us." % describe(code))
        elif kind == "future":
            print("Arrival alert: future era, %s ahead of us." % describe(code))
        elif kind == "present":
            print("Confirmed: returned to present day.")
        else:
            print("Warning: spatial anomaly at code %r." % (code,))
    print("Environmental scan: %s" % scan_report(coordinates))
    print("Paradox warning status: %s" % paradox_level(coordinates))
    for stage in (3, 2, 1):
        print("Engine cooldown stage %d..." % stage)
    print("Engines cold. Flux capacitor offline.")


def main():
