def describe_forager(index):
    print("Bee %d (forager): leaves the hive scanning for clover and linden blossoms." % index)
    print("Bee %d (forager): nectar load logged at 40 mg, pollen baskets nearly full." % index)
    return 40


def describe_guard(index):
    print("Bee %d (guard): patrols the entrance, antennae testing every arrival." % index)
    print("Bee %d (guard): defense report - two wasps turned away, no breach at the gate." % index)
    return 0


def describe_nurse(index):
    print("Bee %d (nurse): moves along the brood comb inspecting capped cells." % index)
    print("Bee %d (nurse): feeding schedule - royal jelly every 20 minutes for 60 larvae." % index)
    return 0


def describe_other(index, role):
    print("Bee %d (%s): drifts across the comb with no task assigned." % (index, role))
    print("Bee %d (%s): resting state observed, wings folded, metabolism low." % (index, role))
    return 0


def document(index, role):
    if role == "forager":
        return describe_forager(index)
    if role == "guard":
        return describe_guard(index)
    if role == "nurse":
        return describe_nurse(index)
    return describe_other(index, role)


def tally(nectar_mg, workers):
    honey_mg = nectar_mg / 3.0
    print("Daily tally: %d bees observed, %d mg of nectar carried home." % (workers, nectar_mg))
    print("Daily tally: that ripens into roughly %.1f mg of sealed honey." % honey_mg)
    return honey_mg


def observe(bees):
    if not isinstance(bees, list):
        raise TypeError("observe() expects a list of insect roles")
    sunrise()
    nectar_mg = 0
    index = 0
    for role in bees:
        index += 1
        nectar_mg += document(index, str(role).strip().lower())
    if index == 0:
        print("The comb is empty today; no roles were available to document.")
    honey_mg = tally(nectar_mg, index)
    print("Sunset: the last foragers land heavy on the board and file inside.")
    print("Nightfall: the hive hums softly, brood covered, guards asleep at the gate.")
    return honey_mg


