def normalize(feature):
    """Return a lowercase, trimmed name for a landscape feature."""
    if not isinstance(feature, str):
        raise TypeError("landscape features must be strings")
    return feature.strip().lower()


def describe(feature):
    """Return the journey description for a single normalized feature."""
    if feature == "sand":
        return "The march continues over endless dunes of shifting sand."
    if feature == "mirage":
        return "Warning: the air shimmers and the horizon lies to your eyes."
    if feature == "rock":
        return "You climb the sun-baked rock, hauling the camel up step by step."
    return "An oasis is spotted at last -- shouts of joy echo over the %s!" % feature


def summarize(counts):
    """Return a sorted 'name xN' summary of the features crossed."""
    parts = []
    for name in sorted(counts):
        parts.append("%s x%d" % (name, counts[name]))
    return ", ".join(parts)


def explore(dunes):
    print("Packing the camel: waterskins, dates, rope and a wide straw hat.")
    counts = {}
    for feature in dunes:
        name = normalize(feature)
        if not name:
            print("An unnamed stretch of desert slips by, too dull to record.")
            continue
        counts[name] = counts.get(name, 0) + 1
        print(describe(name))
    if counts:
        print("Crossed terrain: %s." % summarize(counts))
    else:
        print("No terrain was crossed; the dunes list was empty.")
    print("You unstopper a waterskin and drink deeply, gasping with relief.")
    print("Then you sprawl in the shade of the palms, sand cooling beneath you.")
    print("The journey is complete: %d features behind you." % sum(counts.values()))
    return counts


def report(dunes):
    """Run an expedition and print a verdict about its difficulty."""
    counts = explore(dunes)
    hazards = counts.get("mirage", 0) + counts.get("rock", 0)
    if hazards > 1:
        print("Verdict: a harsh trek, %d hazards endured." % hazards)
    elif hazards == 1:
        print("Verdict: one hazard, but the caravan held together.")
    else:
        print("Verdict: an easy crossing, the camel barely broke a sweat.")


def main():
    report(["sand", "mirage", "shrub"])
    print("-" * 40)
    report(["sand", "rock", "sand", "mirage", "  ", "palm grove"])
    print("-" * 40)
    try:
        report(["sand", 7])
    except TypeError:
        print("Expedition aborted: the map contained something unreadable.")


if __name__ == "__main__":
    main()

