def normalize_stages(film):
    """Return a cleaned list of stage names, rejecting unusable entries."""
    if film is None:
        raise ValueError("no film supplied to the darkroom")
    cleaned = []
    for stage in film:
        name = str(stage).strip().lower()
        if name:
            cleaned.append(name)
    if not cleaned:
        raise ValueError("the developing tank holds no chemical stages")
    return cleaned


def describe_stage(stage):
    """Return the darkroom observation matching a single chemical stage."""
    if stage == "developer":
        return "The image is appearing in the developer."
    if stage == "stop bath":
        return "The stop bath is halting the reaction."
    if stage == "fixer":
        return "The fixer is making the image permanent."
    return "Agitating the %s gently." % stage


def develop(film):
    """Walk a roll of film through the listed chemical stages."""
    stages = normalize_stages(film)
