def normalize(direction):
    """Return a direction string in a canonical, comparable form."""
    if not isinstance(direction, str):
        raise TypeError("direction must be a string, got %r" % (direction,))
    return direction.strip().lower()


def describe(x, y):
    """Render a coordinate pair as a readable phrase."""
    return "coordinates %d %d" % (x, y)


def explore(moves):
    """Walk the maze following moves, narrating every step."""
    if not isinstance(moves, (list, tuple)):
        raise TypeError("moves must be a list of direction strings")
    x = 0
    y = 0
    print("starting coordinates 0 0")
    for raw in moves:
        direction = normalize(raw)
        if direction == "north":
            print("moving north")
            y += 1
        elif direction == "south":
            print("moving south")
            y -= 1
        elif direction == "east":
            print("heading east")
            x += 1
        elif direction == "west":
            print("heading west")
            x -= 1
        elif direction == "jump":
            print("leaping forward")
            x += 2
            y += 2
        elif direction == "wait":
            print("pausing to rest")
        else:
            print("invalid direction %s" % (raw,))
    print("final %s" % describe(x, y))
    return (x, y)


def summarize(label, end):
    """Report where a run of the maze left the explorer."""
    x, y = end
    print("%s ended at %s" % (label, describe(x, y)))
    print("manhattan distance from origin: %d" % (abs(x) + abs(y)))
    if x == 0 and y == 0:
        print("returned to the entry point")


def main():
    runs = [
        ("short hop", ["north", "jump"]),
        ("full tour", ["east", "wait", "south", "west", "spin", "jump"]),
        ("loop back", ["north", "south"]),
    ]
    for label, moves in runs:
        print("--- %s ---" % (label,))
        end = explore(moves)
        summarize(label, end)


if __name__ == "__main__":
    main()

