def add_line(lines, text):
    lines.append(text)
    print("line added %d" % len(lines))


def delete_line(lines):
    if lines:
        lines.pop()
        print("line deleted")
    else:
        print("buffer empty")


def show_buffer(lines):
    print(" ".join(lines))


def save_buffer(lines):
    total = 0
    for line in lines:
        total += len(line)
    print("saving file %d" % total)


def clear_buffer(lines):
    del lines[:]
    print("buffer cleared")


def edit(commands):
    print("starting editor")
    lines = []
    for command in commands:
        instruction = command.strip()
        if instruction.startswith("add"):
            add_line(lines, instruction[3:].strip())
        elif instruction == "delete":
            delete_line(lines)
        elif instruction == "show":
            show_buffer(lines)
        elif instruction == "save":
            save_buffer(lines)
        elif instruction == "clear":
            clear_buffer(lines)
        elif instruction == "exit":
            print("shutting down")
            break
        else:
            print("unknown instruction %s" % instruction)
    return lines


