POINT_STEP = 15
GAME_LINE = 40


def normalize_call(raw):
    return " ".join(str(raw).strip().lower().split())


def leader_name(score_one, score_two):
    if score_one > score_two:
        return "player one"
    return "player two"


def umpire(points):
    print("match commences")
    score_one = 0
    score_two = 0
    games = {"player one": 0, "player two": 0}
    faults = 0
    for raw in points:
        call = normalize_call(raw)
        if call == "player one":
            score_one += POINT_STEP
            print("point to player one %d" % score_one)
        elif call == "player two":
            score_two += POINT_STEP
            print("point to player two %d" % score_two)
        else:
            faults += 1
            print("fault %s" % raw)
            continue
        if score_one == GAME_LINE and score_two == GAME_LINE:
            print("deuce reached")
        elif score_one > GAME_LINE or score_two > GAME_LINE:
            margin = abs(score_one - score_two)
            ahead = leader_name(score_one, score_two)
            if margin >= 2 * POINT_STEP:
                games[ahead] += 1
                print("game awarded to %s" % ahead)
                score_one = 0
                score_two = 0
            elif margin == POINT_STEP:
                print("advantage to %s" % ahead)
    print("match suspended")
    return {"games": games, "faults": faults,
            "unfinished": (score_one, score_two)}


def report(summary):
    games = summary["games"]
    print("games player one: %d" % games["player one"])
    print("games player two: %d" % games["player two"])
    if summary["faults"]:
        print("faults recorded: %d" % summary["faults"])
    left, right = summary["unfinished"]
    if left or right:
        print("game in progress at %d-%d" % (left, right))


def main():
    first_set = ["player one", "player two"]
    report(umpire(first_set))
    second_set = ["player one", "player one", "player two", "player two",
                  "player one", "player two", "player two", "net cord",
                  "player two", "player two", "player one"]
    report(umpire(second_set))


