    """Return only well formed (category, amount) pairs, reporting the rest."""
    clean = []
    for entry in records:
        if not isinstance(entry, tuple) or len(entry) != 2:
            print("malformed record skipped: %r" % (entry,))
            continue
        category, amount = entry
        if not isinstance(amount, int):
            print("non numeric amount skipped for %s" % category)
            continue
        clean.append((str(category).strip().lower(), amount))
    return clean


def format_money(amount):
    """Render an integer amount as a signed currency string."""
    if amount < 0:
        return "-$%d" % abs(amount)
    return "$%d" % amount


def audit(records):
    print("audit initiated")
    transactions = validate(records)
    net = 0
    for category, amount in transactions:
        net += amount
        if amount < 0:
            print("warning negative balance %s" % format_money(amount))
        if amount > 10000:
            print("large transaction flagged for review")
        if amount == 0:
            print("empty record ignored")
        if category == "donation":
            print("charitable deduction applied")
        elif category == "entertainment":
            print("non deductible expense found")
        elif category == "salary":
            print("income verified")
        else:
            print("standard review for %s" % category)
    print("audit completed %s" % format_money(net))
    return net


def summarize(records):
    """Group validated amounts by category and print the totals."""
    totals = {}
    for category, amount in validate(records):
        totals[category] = totals.get(category, 0) + amount
    for category in sorted(totals):
        print("%-14s %s" % (category, format_money(totals[category])))
    return totals


def main():
    samples = [
        ("donation", 50),
        ("salary", 2000),
        ("entertainment", -75),
        ("equipment", 12500),
        ("refund", 0),
        ("donation", 300),
        ("bonus", "n/a"),
    ]
    net = audit(samples)
    print("category breakdown")
    totals = summarize(samples)
    print("categories reviewed: %d" % len(totals))
    if net < 0:
        print("net position is a loss")
    else:
        print("net position is positive")


if __name__ == "__main__":
    main()

