text_nat:
def normalize(terrain):
    """Return a cleaned, lower-case terrain label."""
    return str(terrain).strip().lower()


def clean_commands(commands):
    """Drop blank entries and normalise the terrain labels."""
    cleaned = []
    for raw in commands:
        label = normalize(raw)
        if label:
            cleaned.append(label)
    return cleaned


def drive(commands):
    """Drive the rover over a list of terrains, returning a handling report."""
    print("rover activated")
    terrains = clean_commands(commands)
    report = {"handled": 0, "halted": False}
    for index, terrain in enumerate(terrains):
        if terrain == "crater":
            print("adjusting suspension for crater")
        elif terrain == "rock":
            print("deploying rock drill")
            print("current step index: %d" % index)
        elif terrain == "sand":
            print("engaging four wheel drive for sand")
        elif terrain == "ice":
            print("melting ice for water sample")
        elif terrain == "alien":
            print("transmitting unknown lifeform data to earth")
            report["halted"] = True
            report["handled"] = index + 1
            return report
        elif terrain == "dust":
            print("wiping solar panels")
        else:
            print("normal driving over %s" % terrain)
        report["handled"] = index + 1
    print("rover entering sleep mode")
    return report


def summarize(name, report):
    """Print a short mission summary for one drive run."""
    print("--- summary for %s ---" % name)
    print("terrains handled: %d" % report["handled"])
    if report["halted"]:
        print("mission interrupted by alien contact")
    else:
        print("mission completed nominally")


def main():
    runs = [
        ("short survey", ["crater", "dust"]),
        ("mixed traverse", ["sand", "rock", "ice", "gravel", "dust"]),
        ("first contact", ["rock", "alien", "crater", "sand"]),
        ("noisy uplink", ["  Crater ", "", "ROCK", "swamp"]),
    ]
    for name, commands in runs:
        print("=== run: %s ===" % name)
        report = drive(commands)
        summarize(name, report)
    print("all runs finished")


if __name__ == "__main__":
    main()

