text_nat:
AGGRESSIVE_WORDS = ("stupid", "idiot", "shut up", "whatever, dude", "hate you")
HUMOROUS_MARKERS = ("haha", "lol", "just kidding", "joke", ":)")
CONFUSED_MARKERS = ("what?", "huh", "i don't understand", "come again", "sorry?")
SILENCE_FORMS = ("", "...", "--", "-")


def classify(response):
    text = response.strip().lower()
    if text in SILENCE_FORMS:
        return "silence"
    for word in AGGRESSIVE_WORDS:
        if word in text:
            return "aggressive"
    for marker in HUMOROUS_MARKERS:
        if marker in text:
            return "humorous"
    for marker in CONFUSED_MARKERS:
        if marker in text:
            return "confused"
    words = text.split()
    if len(words) <= 4:
        return "brief"
    if len(words) >= 20:
        return "comprehensive"
    return "other"


def react(kind, response):
    if kind == "brief":
        print("Could you please give me more details?")
    elif kind == "comprehensive":
        print("Excellent communication skills noted.")
    elif kind == "confused":
        print("Let me repeat the question for you.")
    elif kind == "silence":
        print("Awkward pause detected.")
    elif kind == "aggressive":
        print("Candidate rejected due to attitude.")
    elif kind == "humorous":
        print("Ha ha! Bonus points for that one.")
    else:
        print("Writing down notes: %s" % response.strip())
    return kind != "aggressive"


def interview(responses):
    print("Starting interview process...")
    for index, response in enumerate(responses):
        print("Question %d asked." % (index + 1))
        kind = classify(response)
        if not react(kind, response):
            print("Interview terminated early.")
            return "rejected"
    print("Scheduling follow up round.")
    return "passed"


if __name__ == "__main__":
    candidate_a = ["Yes.", "   "]
    print("--- Candidate A ---")
    print("Result: %s" % interview(candidate_a))
    candidate_b = [
        "I led a team of five engineers through a full migration of our billing "
        "platform, coordinating releases and mentoring two junior developers "
        "along the way every single sprint.",
        "Huh, come again?",
        "lol, my last manager said the same thing",
        "I usually plan my week on Monday morning and adjust as needed.",
    ]
    print("--- Candidate B ---")
    print("Result: %s" % interview(candidate_b))
    candidate_c = ["That question is stupid.", "Anyway, next?"]
    print("--- Candidate C ---")
    print("Result: %s" % interview(candidate_c))

