def normalize(command):
    return command.strip().lower()


def do_sit(state):
    state["treats"] += 1
    print("Dog sits and receives a treat.")


def do_stay(state):
    state["obedience"] += 1
    print("Dog stays in place.")


def do_fetch(state):
    state["throws"] += 1
    print("Dog chases the ball, throw number %d." % state["throws"])


def do_roll(state):
    state["obedience"] += 1
    print("Dog rolls over happily.")


def do_jump(state):
    state["scoldings"] += 1
    print("Dog jumps up and gets a scolding.")


def do_bark(state):
    state["obedience"] += 1
    print("Dog barks loudly at a squirrel.")


def do_unknown(state, command):
    state["confusions"] += 1
    print("Dog tilts head in confusion at '%s'." % command)


ACTIONS = {
    "sit": do_sit,
    "stay": do_stay,
    "fetch": do_fetch,
    "roll": do_roll,
    "jump": do_jump,
    "bark": do_bark,
}


def report(state):
    print("Treats earned: %d" % state["treats"])
    print("Good behaviours: %d" % state["obedience"])
    print("Scoldings given: %d" % state["scoldings"])
    print("Confused moments: %d" % state["confusions"])


def train(commands):
    state = {"treats": 0, "throws": 0, "obedience": 0, "scoldings": 0, "confusions": 0}
    print("Training session begins.")
    for command in commands:
        key = normalize(command)
        action = ACTIONS.get(key)
        if action is None:
            do_unknown(state, command)
        else:
            action(state)
    print("Training session over.")
    report(state)
    return state


if __name__ == "__main__":
    session = train(["sit", "roll", "fetch", "jump", "Fetch", "bark", "dance", "stay"])
    if session["scoldings"] > 0:
        print("The dog needs more practice tomorrow.")
    else:
        print("A perfectly behaved dog today.")

