text_nat:
def normalize(action):
    """Reduce a raw action string to a comparable keyword."""
    return str(action).strip().lower()


def handle_demand(tension):
    print("rejecting outrageous demand")
    return tension + 1


def handle_concede(tension):
    print("accepting concession")
    return tension - 1


def handle_threaten(tension):
    print("issuing counter threat")
    return tension + 2


def handle_bribe(tension):
    print("refusing unethical offer")
    print("reporting to council")
    return tension


def handle_apologize(tension):
    print("accepting formal apology")
    return tension


def handle_propose(tension, index):
    print("reviewing proposal carefully")
    print("proposal index: %d" % index)
    return tension


def handle_other(tension):
    print("noting diplomatic pleasantry")
    return tension


def negotiate(dialogues):
    if not isinstance(dialogues, (list, tuple)):
        raise TypeError("dialogues must be a list of action strings")
    print("summit started")
    tension = 0
    for index, raw in enumerate(dialogues):
        action = normalize(raw)
        if action == "demand":
            tension = handle_demand(tension)
        elif action == "concede":
            tension = handle_concede(tension)
        elif action == "threaten":
            tension = handle_threaten(tension)
        elif action == "bribe":
            tension = handle_bribe(tension)
        elif action == "apologize":
            tension = handle_apologize(tension)
        elif action == "propose":
            tension = handle_propose(tension, index)
        else:
            tension = handle_other(tension)
    print("summit concluded")
    print("final tension level: %d" % tension)
    return tension


def assess(tension):
    """Turn a final tension level into a short diplomatic verdict."""
    if tension <= 0:
        return "relations improved"
    if tension < 4:
        return "relations strained"
    return "relations near collapse"


def main():
    rounds = [
        ["apologize", "demand"],
        ["propose", "threaten", "bribe", "concede", "smile"],
    ]
    for number, dialogues in enumerate(rounds, 1):
        print("=== round %d ===" % number)
        tension = negotiate(dialogues)
        print(assess(tension))


if __name__ == "__main__":
    main()

