text_nat:
def normalize(action):
    return " ".join(str(action).lower().split())


def buy_silk(purse):
    purse["coins"] -= 12
    print("Purchasing fine silk for coins.")


def sell_spices(purse):
    purse["coins"] += 20
    print("Trading spices for profit.")


def haggle(purse):
    purse["haggles"] += 1
    print("Arguing over prices with a local merchant.")


def pay_tax(purse):
    purse["coins"] -= 5
    print("Paying the local lord a tariff.")


def rest(purse):
    purse["coins"] -= 2
    print("Staying at a local inn to recover.")


def exchange_common(purse):
    purse["coins"] += 1
    print("Exchanging common goods.")


HANDLERS = {
    "buy silk": buy_silk,
    "sell spices": sell_spices,
    "haggle": haggle,
    "tax": pay_tax,
    "rest": rest,
}


def trade(actions):
    print("Market stalls open.")
    purse = {"coins": 50, "haggles": 0}
    for action in actions:
        step = normalize(action)
        if step == "bandit":
            purse["coins"] = 0
            print("Losing goods to a bandit ambush.")
            print("The journey is stopped completely.")
            return purse
        handler = HANDLERS.get(step, exchange_common)
        handler(purse)
    print("Arriving safely at the final destination.")
    return purse


def report(purse):
    print("Purse after the journey: %d coins." % purse["coins"])
    if purse["haggles"]:
        print("Haggled with %d merchant(s) along the way." % purse["haggles"])


def main():
    journey = ["buy silk", "tax", "haggle", "sell spices", "pottery", "rest"]
    report(trade(journey))
    print("---")
    ambushed = ["buy silk", "bandit", "sell spices"]
    report(trade(ambushed))


if __name__ == "__main__":
    main()

