KEYWORDS = (
    ("forgery", ("forgery", "forged", "fake", "counterfeit")),
    ("painting", ("painting", "canvas", "portrait")),
    ("coin", ("coin", "penny", "doubloon")),
    ("furniture", ("furniture", "chair", "table", "cabinet")),
    ("jewelry", ("jewelry", "jewellery", "necklace", "ring", "brooch")),
    ("toy", ("toy", "doll", "train set")),
)


def normalize(description):
    if not isinstance(description, str):
        raise TypeError("each item must be a description string")
    return description.strip().lower()


def classify(description):
    text = normalize(description)
    if not text:
        return "blank"
    for category, words in KEYWORDS:
        for word in words:
            if word in text:
                return category
    return "other"


def summarize(counts):
    print("Appraisal summary:")
    for category in sorted(counts):
        print(" - %s: %d" % (category, counts[category]))


def appraise(items):
    print("Setting up the appraisal table.")
    counts = {}
    for item in items:
        category = classify(item)
        counts[category] = counts.get(category, 0) + 1
        if category == "blank":
            print("Skipping an item with no description.")
        elif category == "painting":
            print("Examining the brushstrokes and signature.")
        elif category == "coin":
            print("Checking the mint mark and wear level.")
        elif category == "furniture":
            print("Inspecting the dovetail joints and wood type.")
        elif category == "jewelry":
            print("Testing the gemstones and metal purity.")
        elif category == "forgery":
            print("Calling security and confiscating the fake.")
            print("Halting the appraisal session.")
            summarize(counts)
            return counts
        elif category == "toy":
            print("Checking the original packaging and moving parts.")
        else:
            print("Giving a rough estimate based on condition.")
    print("Packing up the magnifying glass.")
    summarize(counts)
    return counts


