def validate(actions):
    """Return a cleaned list of (action, temperature) pairs."""
    cleaned = []
    for item in actions:
        if len(item) != 2:
            raise ValueError("each entry needs an action and a temperature")
        action, temp = item
        cleaned.append((str(action).strip().lower(), int(temp)))
    return cleaned


def describe(action, temp):
    """Return the message for a single step of the process."""
    if action == "gather":
        return "Gathering molten glass at %d degrees." % temp
    if action == "roll":
        return "Shaping the gather on the marver."
    if action == "puff":
        return "Blowing air into the pipe."
    if action == "swing":
        return "Swinging the pipe to elongate the shape."
    if action == "detach":
        return "Transferring the piece to the punty."
    if action == "anneal":
        return "Placing the piece in the cooler to anneal."
    return "Pausing to inspect the piece."


def blow(actions):
    steps = validate(actions)
    print("The studio furnace is hot and ready.")
    for action, temp in steps:
        print(describe(action, temp))
        if temp > 2000:
            print("Warning: intense heat, keep your distance!")
    print("Session complete: %d steps taken." % len(steps))
    return len(steps)


def temperature_report(actions):
    """Summarise the heat used across a session."""
    steps = validate(actions)
    temps = [temp for _action, temp in steps]
    if not temps:
        print("No temperatures recorded.")
        return
    print("Hottest step: %d degrees." % max(temps))
    print("Coolest step: %d degrees." % min(temps))
    average = sum(temps) / float(len(temps))
    print("Average working heat: %.1f degrees." % average)


def main():
    vase = [("gather", 2100), ("puff", 1000)]
    blow(vase)
    temperature_report(vase)

    print("---")
    goblet = [
        ("gather", 2150),
        ("roll", 1900),
        ("puff", 1600),
        ("swing", 1500),
        ("stretch", 1400),
        ("detach", 1300),
        ("anneal", 900),
    ]
    total = blow(goblet)
    if total > 5:
        print("That was a long session at the bench.")
    temperature_report(goblet)


if __name__ == "__main__":
    main()

