def wind_category(speed):
    if speed > 15:
        return "high"
    if speed < 5:
        return "low"
    return "moderate"


def validate_conditions(conditions):
    checked = []
    for index, item in enumerate(conditions):
        if len(item) != 2:
            raise ValueError("condition %d must hold a speed and an altitude" % index)
        speed, altitude = item
        if not isinstance(speed, int) or not isinstance(altitude, int):
            raise ValueError("condition %d must use integers" % index)
        if speed < 0 or altitude < 0:
            raise ValueError("condition %d must not be negative" % index)
        checked.append((speed, altitude))
    return checked


def fly(conditions):
    print("Starting the inflation fan.")
    print("Igniting the main burner.")
    tally = {"high": 0, "low": 0, "moderate": 0}
    for speed, altitude in validate_conditions(conditions):
        category = wind_category(speed)
        tally[category] += 1
        if category == "high":
            print("Aborting the ascent due to high winds.")
        elif category == "low" and altitude < 1000:
            print("Gently rising above the treetops.")
        elif altitude > 3000:
            print("Blasting the burner for a high altitude climb.")
        elif altitude == 0:
            print("Preparing for a smooth landing.")
        elif category == "moderate":
            print("Drifting steadily over the countryside.")
        else:
            print("Holding the current altitude of %d feet." % altitude)
    print("Packing the envelope into the bag.")
    print("Celebrating with a traditional toast.")
    return tally


def report(tally):
    total = sum(tally.values())
    print("Legs flown: %d" % total)
    for category in ("low", "moderate", "high"):
        print("%s winds: %d leg(s)" % (category.capitalize(), tally[category]))
    if tally["high"]:
        print("Debrief: review the weather window before the next flight.")
    else:
        print("Debrief: conditions stayed inside the safety envelope.")


def main():
    flight = [(3, 800), (7, 2500), (4, 3600), (2, 0), (18, 1200)]
    tally = fly(flight)
    report(tally)
    try:
        fly([(5, -20)])
    except ValueError as error:
        print("Flight rejected: %s" % error)


if __name__ == "__main__":
    main()

