def validate(batches):
    """Return the batches with quantities coerced to int, rejecting bad rows."""
    clean = []
    for entry in batches:
        if len(entry) != 3:
            raise ValueError("each batch needs album, color and quantity")
        album, color, quantity = entry
        quantity = int(quantity)
        if quantity <= 0:
            raise ValueError("quantity for %s must be positive" % album)
        clean.append((album, color.lower(), quantity))
    return clean


def press(batches):
    batches = validate(batches)
    print("Turning on the steam valves to heat the press.")
    print("Securing the metal stampers into the plates.")
    pressed = 0
    for album, color, quantity in batches:
        print("Loading batch: %s (%s), %d units." % (album, color, quantity))
        if color == "black":
            print("Extruding a standard black vinyl puck.")
        if color == "splatter":
            print("Mixing base color pellets with contrasting beads.")
        if color == "clear":
            print("Ensuring the hopper is completely clean of dust.")
        if quantity > 500:
            print("Starting a long continuous pressing run.")
        if quantity < 50:
            print("Monitoring closely for a short custom run.")
        print("Dropping the puck onto the spindle.")
        print("Closing the press with 150 tons of pressure.")
        pressed += quantity
    print("Turning off the steam.")
    print("Opening the cooling water valves.")
    return pressed


def summarize(batches):
    """Group the requested quantities by color variant."""
    totals = {}
    for album, color, quantity in validate(batches):
        totals[color] = totals.get(color, 0) + quantity
    return totals


def report(totals, pressed):
    for color in sorted(totals):
        print("  %-10s %5d records" % (color, totals[color]))
    print("Total records pressed: %d" % pressed)


