def normalize_step(step):
    tool, wetness, action = step
    return (tool.strip().lower(), wetness.strip().lower(), action.strip().lower())


def describe_step(index, step):
    return "Step %d: %s / %s sand / %s" % (index, step[0], step[1], step[2])


def handle_bucket(wetness):
    if wetness == "high":
        print("Packing dense mud into the bucket for a solid tower.")
        return True
    if wetness == "low":
        print("Struggling because the dry sand crumbles away.")
        return True
    return False


def handle_action(tool, action):
    if tool == "shovel" and action == "moat":
        print("Carving a deep trench around the perimeter.")
        return True
    if tool == "trowel" and action == "windows":
        print("Carefully scraping out small square openings.")
        return True
    if tool == "hands" and action == "wall":
        print("Patting the sand together to form a sturdy barrier.")
        return True
    if tool == "stick" and action == "texture":
        print("Drawing brick patterns into the facade.")
        return True
    return False


def sculpt(steps):
    print("Finding a flat spot near the high tide line.")
    print("Digging a large hole to reach ground water.")
    handled = 0
    skipped = []
    for number, raw in enumerate(steps, 1):
        step = normalize_step(raw)
        print(describe_step(number, step))
        tool, wetness, action = step
        done = False
        if tool == "bucket":
            done = handle_bucket(wetness)
        if not done:
            done = handle_action(tool, action)
        if done:
            handled += 1
        else:
            skipped.append(number)
    print("Placing a small flag on the highest peak.")
    print("Taking a picture before the ocean washes it away.")
    print("Completed %d of %d planned steps." % (handled, len(steps)))
    if skipped:
        print("Unrecognized steps: %s" % ", ".join(str(n) for n in skipped))
    return handled


def main():
    plan = [
        ("bucket", "high", "tower"),
        ("bucket", "low", "tower"),
        ("shovel", "medium", "moat"),
        ("trowel", "medium", "windows"),
        ("hands", "high", "wall"),
        ("stick", "low", "texture"),
        ("rake", "high", "garden"),
    ]
    finished = sculpt(plan)
    if finished == len(plan):
        print("The whole castle went exactly as designed.")


if __name__ == "__main__":
    main()

