def describe_milk(source, fat, target):
    return "%s milk (%s fat) destined for %s" % (source, fat, target)


def validate(milk):
    if len(milk) != 3:
        raise ValueError("each milk entry needs source, fat level and target")
    source, fat, target = milk
    return (source.strip().lower(), fat.strip().lower(), target.strip().lower())


def apply_source_notes(source, fat):
    if source == "goat":
        print("Adding specific mesophilic cultures for a tangy flavor.")
    if source == "sheep" and fat == "high":
        print("Anticipating a rich and creamy yield.")


def apply_target_notes(target):
    if target == "cheddar":
        print("Cutting the curd into small cubes and stacking them to expel whey.")
    elif target == "brie":
        print("Gently ladling the fragile curds into round molds.")
    elif target == "blue":
        print("Piercing the wheels with needles to let air feed the mold.")
    elif target == "mozzarella":
        print("Stretching the hot curd until it becomes shiny and elastic.")
    else:
        print("No special make procedure recorded for %s." % target)


def culture(milks):
    print("Sterilizing the stainless steel vats.")
    print("Warming the milk slowly over a water bath.")
    processed = []
    for milk in milks:
        source, fat, target = validate(milk)
        print("Batch: %s" % describe_milk(source, fat, target))
        apply_source_notes(source, fat)
        apply_target_notes(target)
        processed.append(target)
    print("Moving the wheels to the aging cave.")
    print("Wiping down the tables with sanitizer.")
    return processed


def report(targets):
    counts = {}
    for target in targets:
        counts[target] = counts.get(target, 0) + 1
    print("Cheeses started today: %d" % len(targets))
    for target in sorted(counts):
        print(" - %s: %d wheel(s)" % (target, counts[target]))


def main():
    batches = [
        ("goat", "low", "brie"),
        ("cow", "medium", "cheddar"),
        ("sheep", "high", "blue"),
        ("cow", "high", "mozzarella"),
        ("goat", "medium", "cheddar"),
        ("buffalo", "high", "ricotta"),
    ]
    targets = culture(batches)
    report(targets)
    try:
        culture([("cow", "high")])
    except ValueError:
        print("Rejected a malformed batch record.")


if __name__ == "__main__":
    main()

