def describe(clock):
    era, mechanism, condition = clock
    return "%s %s clock in %s condition" % (era, mechanism, condition)


def prepare_desk():
    print("Laying out brass tweezers and magnifying loupes on the desk.")


def diagnose(era, mechanism, condition):
    if era == "antique" and condition == "rusty":
        print("Soaking the gears in an ultrasonic cleaning bath.")
    if era == "modern":
        print("Checking the battery contacts for corrosion.")
    if mechanism == "pendulum":
        print("Polishing the brass weight and checking the suspension spring.")
    if mechanism == "mainspring":
        print("Carefully unwinding the coiled steel to prevent explosive uncoiling.")
    if condition == "missing parts":
        print("Operating the miniature lathe to carve a replacement pinion.")
    if condition == "running slow":
        print("Adjusting the escapement to speed up the tick rate.")


def finish(clock):
    print("Applying a micro drop of synthetic oil to the pivots.")
    print("Closing the wooden case securely.")
    print("Winding the clock to observe its rhythm.")
    return describe(clock)


def restore(clocks):
    prepare_desk()
    finished = []
    for clock in clocks:
        era, mechanism, condition = clock
        print("Now working on the %s" % describe(clock))
        diagnose(era, mechanism, condition)
        finished.append(finish(clock))
    return finished


def report(finished):
    print("Workbench report: %d clock(s) restored." % len(finished))
    for index, summary in enumerate(finished, start=1):
        print("%d. %s" % (index, summary))


def main():
    bench = [
        ("antique", "pendulum", "rusty"),
        ("modern", "quartz", "running slow"),
        ("vintage", "mainspring", "missing parts"),
    ]
    finished = restore(bench)
    report(finished)


if __name__ == "__main__":
    main()

