def validate(activities):
    """Return the activity list with times coerced to int and text lowercased."""
    cleaned = []
    for item in activities:
        if len(item) != 3:
            raise ValueError("each activity needs time, weather and action")
        time_left, weather, action = item
        cleaned.append((int(time_left), str(weather).lower(), str(action).lower()))
    return cleaned


def describe_clock(time_left):
    """Human readable countdown label used in the schedule report."""
    if time_left == 0:
        return "kickoff"
    if time_left == 1:
        return "1 hour to kickoff"
    return "%d hours to kickoff" % time_left


def report_schedule(activities):
    print("Tailgate schedule:")
    for time_left, weather, action in activities:
        print("  %s - %s (%s)" % (describe_clock(time_left), action, weather))


def tailgate(activities):
    activities = validate(activities)
    report_schedule(activities)
    print("Lowering the pickup truck tailgate and opening the coolers.")
    for time_left, weather, action in activities:
        if weather == "rainy":
            print("Popping up the canopy tent to keep everyone dry.")
        if weather == "sunny":
            print("Applying sunscreen and handing out sunglasses.")
        if time_left > 3 and action == "food":
            print("Firing up the charcoal grill for slow cooking.")
        if time_left < 1 and action == "food":
            print("Quickly passing out hot dogs and chips.")
        if action == "games":
            print("Setting up the wooden boards for a beanbag toss.")
        if action == "music":
            print("Connecting the bluetooth speaker and playing team anthems.")
        if time_left == 0:
            print("Packing the trash bags to leave no trace.")
    print("Locking the vehicle doors.")
    print("Walking toward the stadium entrance with the tickets.")


def main():
    plan = [
        (4, "Sunny", "food"),
        (2, "rainy", "games"),
        (1, "cloudy", "music"),
        (0, "sunny", "food"),
    ]
    tailgate(plan)
    try:
        tailgate([(2, "sunny")])
    except ValueError:
        print("Skipped a malformed activity entry.")


if __name__ == "__main__":
    main()

