HIGH_CUT_THRESHOLD = 6

AUTOMOTIVE = "automotive"
RESIDENTIAL = "residential"
STEEL = "steel"
ALUMINUM = "aluminum"


def parse_key(entry):
    profile, metal, cuts = entry
    return (str(profile).strip().lower(), str(metal).strip().lower(), int(cuts))


def prepare_blank(profile):
    if profile == AUTOMOTIVE:
        print("Inserting a transponder blank and programming the chip.")
    elif profile == RESIDENTIAL:
        print("Clamping a standard brass blank into the vice.")
    else:
        print("Profile '%s' is unfamiliar; selecting a generic blank by eye." % profile)


def cut_metal(metal):
    if metal == STEEL:
        print("Feeding the blade slowly to avoid sparking and wearing down the cutter.")
    elif metal == ALUMINUM:
        print("Sliding the carriage quickly through the soft metal.")
    else:
        print("Setting an average feed rate for %s stock." % metal)


def follow_pattern(cuts):
    if cuts >= HIGH_CUT_THRESHOLD:
        print("Meticulously tracing the many deep peaks and valleys.")
    else:
        print("Making a few simple passes along the edge.")


def finish_key(index):
    print("Key %d: running the new key against the wire brush to remove sharp burrs." % index)
    print("Key %d: handing the copy to the customer." % index)


def duplicate(keys):
    print("Turning on the grinding wheel motor.")
    made = 0
    for entry in keys:
        profile, metal, cuts = parse_key(entry)
        made += 1
        print("Starting job %d: %s key in %s with %d cuts." % (made, profile, metal, cuts))
        prepare_blank(profile)
        cut_metal(metal)
        follow_pattern(cuts)
        finish_key(made)
    print("Sweeping the metal shavings off the workbench.")
    return made


def report(orders, copies):
    print("Orders received: %d" % orders)
    print("Copies completed: %d" % copies)
    if copies < orders:
        print("Some orders were skipped; check the blank inventory.")


def main():
    orders = [
        ("automotive", "steel", 8),
        ("residential", "brass", 5),
        ("Residential", "Aluminum", 7),
        ("industrial", "steel", 3),
    ]
    copies = duplicate(orders)
    report(len(orders), copies)


if __name__ == "__main__":
    main()

