def describe_oil(oil_type):
    if oil_type == "olive":
        print("Pouring the golden liquid to create a gentle castile bar.")
    if oil_type == "coconut":
        print("Melting the solid fat to guarantee a rich lather.")


def describe_scent(scent):
    if scent == "lavender":
        print("Stirring in the essential oil as the mixture reaches trace.")
    if scent == "unscented":
        print("Leaving the batter pure for sensitive skin.")


def describe_additive(additive):
    if additive == "oatmeal":
        print("Folding in the oats for a soothing exfoliating texture.")
    if additive == "clay":
        print("Whisking the colored powder in a separate cup to avoid lumps.")


def saponify(batches):
    print("Putting on safety goggles and thick rubber gloves.")
    print("Mixing the lye crystals into the distilled water outdoors.")
    for oil_type, scent, additive in batches:
        describe_oil(oil_type)
        describe_scent(scent)
        describe_additive(additive)
    print("Pouring the thick batter into the silicone loaf molds.")
    print("Covering the molds with towels to insulate the heat.")


def parse_batch(line):
    parts = [field.strip().lower() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError("each batch needs oil, scent and additive: %r" % line)
    return tuple(parts)


def read_batches(lines):
    batches = []
    for line in lines:
        if line.strip():
            batches.append(parse_batch(line))
    return batches


def summarize(batches):
    print("Planned batches: %d" % len(batches))
    for index, batch in enumerate(batches, start=1):
        print("  %d. %s oil / %s / %s" % ((index,) + batch))


