def describe_script(style):
    if style == "gothic":
        print("Forming sharp angular letters with precise stops.")
    elif style == "copperplate":
        print("Writing continuous flowing loops with elegant flourishes.")


def describe_pen(pen):
    if pen == "brush":
        print("Sweeping the tip lightly for varying line thicknesses.")
    elif pen == "broad":
        print("Holding the edge at a consistent forty five degree angle.")


def describe_pressure(pressure):
    if pressure == "heavy":
        print("Spreading the tines to release a thick pool of ink.")
    elif pressure == "light":
        print("Barely touching the paper to create a hairline stroke.")


def normalize(stroke):
    if len(stroke) != 3:
        raise ValueError("each stroke needs a style, a pen and a pressure")
    return tuple(str(part).strip().lower() for part in stroke)


def write(strokes):
    print("Ruling light pencil guidelines onto the parchment.")
    print("Dipping the nib into the black iron gall ink.")
    counted = {}
    for stroke in strokes:
        style, pen, pressure = normalize(stroke)
        describe_script(style)
        describe_pen(pen)
        describe_pressure(pressure)
        counted[style] = counted.get(style, 0) + 1
    print("Wiping the metal nibs clean with a damp cloth.")
    print("Leaving the paper flat on the desk to dry completely.")
    return counted


def report(counted):
    if not counted:
        print("No strokes were practised today.")
        return
    for style in sorted(counted):
        print("%s: %d stroke(s)" % (style.capitalize(), counted[style]))
    print("Total strokes practised: %d" % sum(counted.values()))


def main():
    practice = [
        ("gothic", "broad", "heavy"),
        ("Copperplate", "brush", "light"),
        ("gothic", "brush", "light"),
        ("italic", "broad", "medium"),
    ]
    counted = write(practice)
    report(counted)
    try:
        write([("gothic", "broad")])
    except ValueError as err:
        print("Skipped a malformed stroke: %s" % err)


if __name__ == "__main__":
    main()

