KNOWN_STRENGTHS = ("weak", "strong", "gale")


def assemble_kite():
    print("Assembling the fiberglass rods into the nylon sail.")
    print("Tying the thick string to the plastic bridle.")


def normalize(gust):
    if len(gust) != 3:
        raise ValueError("each gust needs a strength, a direction and an action")
    strength, direction, action = gust
    return (strength.strip().lower(), direction.strip().lower(), action.strip().lower())


def report_unknown(strength):
    if strength not in KNOWN_STRENGTHS:
        print("Unrecognized wind strength '%s', reading the flag instead." % strength)


def handle_gust(strength, direction, action):
    events = 0
    if strength == "strong" and action == "launch":
        print("Letting go as the kite immediately shoots into the sky.")
        events += 1
    if strength == "weak":
        print("Running backward desperately to generate some artificial lift.")
        events += 1
    if direction == "shifting":
        print("Watching the kite spin out of control toward the ground.")
        events += 1
    if direction == "steady":
        print("Standing still and letting the string slide through the fingers.")
        events += 1
    if action == "dive":
        print("Pulling the right line hard to execute a dramatic swoop.")
        events += 1
    if strength == "gale":
        print("Struggling to hold onto the plastic handle as it digs into the palm.")
        events += 1
    return events


def pack_up():
    print("Reeling the string back in a figure eight pattern.")
    print("Folding the fabric neatly into its carrying sleeve.")


def soar(gusts):
    assemble_kite()
    total = 0
    for number, gust in enumerate(gusts, 1):
        strength, direction, action = normalize(gust)
        print("Gust %d: %s wind blowing %s, preparing to %s." % (number, strength, direction, action))
        report_unknown(strength)
        handled = handle_gust(strength, direction, action)
        if handled == 0:
            print("Nothing to do but wait for the air to move again.")
        total += handled
    pack_up()
    print("Reacted to %d moments across %d gusts." % (total, len(gusts)))
    return total


def main():
    session = [
        ("strong", "steady", "launch"),
        ("weak", "shifting", "hover"),
        ("gale", "steady", "dive"),
        ("breezy", "calm", "glide"),
    ]
    soar(session)


if __name__ == "__main__":
    main()

