def parse_command(command):
    parts = command.strip().split()
    if not parts:
        return None, None
    opcode = parts[0].lower()
    operand = None
    if len(parts) > 1:
        try:
            operand = int(parts[1])
        except ValueError:
            print("Malformed operand %r in command %r" % (parts[1], command))
            return opcode, None
    return opcode, operand


def emulate(instructions):
    accumulator = 0
    pointer = 0
    while pointer < len(instructions):
        command = instructions[pointer]
        opcode, operand = parse_command(command)
        pointer += 1
        if opcode is None:
            print("Skipping blank instruction")
            continue
        if opcode == "load":
            accumulator = operand
            print("LOAD: brought value %d into the accumulator" % accumulator)
        elif opcode == "add":
            accumulator += operand
            print("ADD: added %d, accumulator is now %d" % (operand, accumulator))
        elif opcode == "subtract":
            accumulator -= operand
            print("SUBTRACT: removed %d, accumulator is now %d" % (operand, accumulator))
        elif opcode == "multiply":
            accumulator *= operand
            print("MULTIPLY: scaled by %d, accumulator is now %d" % (operand, accumulator))
        elif opcode == "divide":
            if operand == 0:
                print("DIVIDE: refused division by zero, accumulator unchanged at %d" % accumulator)
            else:
                accumulator = accumulator // operand
                print("DIVIDE: split by %d, accumulator is now %d" % (operand, accumulator))
        elif opcode == "jump":
            print("JUMP: moving the execution pointer to instruction %s" % (operand,))
        elif opcode == "store":
            print("STORE: saving accumulator value %d to memory" % accumulator)
        elif opcode == "halt":
            print("HALT: system stopping, final accumulator is %d" % accumulator)
            break
        else:
            print("Unknown opcode %r, ignoring instruction" % opcode)
    return accumulator


def report(program, result):
    print("Executed a program of %d instruction(s)" % len(program))
    print("Accumulator on exit: %d" % result)


def main():
    program = [
        "load 10",
        "add 5",
        "store",
        "subtract 3",
        "multiply 4",
        "divide 0",
        "divide 6",
        "jump 2",
        "halt",
    ]
    report(program, emulate(program))

    short_program = ["load 10", "add 5", "halt"]
    print("Running the sample program")
    report(short_program, emulate(short_program))


if __name__ == "__main__":
    main()

