ACTIONS = (
    "north, south, east, west - walk around",
    "look - examine your surroundings",
    "inventory - check your backpack",
    "take - pick something up",
    "drop - put something down",
    "help - show this list",
    "quit - leave the game",
)


def show_help():
    print("You can do the following:")
    for action in ACTIONS:
        print("  " + action)


def normalize(command):
    return str(command).strip().lower()


def parse(commands):
    for raw in commands:
        command = normalize(raw)
        if command in DIRECTIONS:
            print("You walk %s, your steps echoing in the passage." % command)
        elif command == "look":
            print("Dark stone walls surround you, damp and streaked with moss.")
        elif command == "inventory":
            print("Your backpack is empty.")
        elif command == "take":
            print("There is nothing here to grab.")
        elif command == "drop":
            print("You have nothing to leave behind.")
        elif command == "help":
            show_help()
        elif command == "quit":
            print("Farewell, traveller.")
            return
        elif command == "":
            print("You say nothing at all.")
        else:
            print("You cannot '%s' here." % command)


