        print("(empty directory)")
        return
    for entry in entries:
        print(entry)


def show_manual():
    print("MANUAL: This shell understands a small fixed set of words.")
    print("Use 'list' to see files, 'path' to print where you are,")
    print("'clear' to wipe the screen, 'user' for the login name,")
    print("'network' for the address, 'time' for the clock,")
    print("and 'exit' to close the session.")


def mock_timestamp():
    return "2026-09-18 11:42:07 UTC"


def fake_address():
    return "192.168.14.203"


def dispatch(command, path):
    if command == "list":
        list_directory(path)
    elif command == "path":
        print(path)
    elif command == "clear":
        print("[screen cleared]")
    elif command == "manual":
        show_manual()
    elif command == "user":
