def classify(magnitude):
    if magnitude == 0:
        return "silence"
    if magnitude < 2:
        return "micro"
    if magnitude < 3:
        return "minor"
    if magnitude < 4:
        return "rattling"
    if magnitude < 5:
        return "falling"
    if magnitude < 6:
        return "structural"
    if magnitude < 7:
        return "severe"
    return "catastrophic"


def assessment(category):
    messages = {
        "silence": "Complete tectonic silence: no seismic activity detected.",
        "micro": "Micro tremor: detectable only by sensitive instruments.",
        "minor": "Minor shaking notice: felt by people at rest indoors.",
        "rattling": "Noticeable rattling indoors: dishes and windows disturbed.",
        "falling": "Warning: objects may fall from shelves and walls.",
        "structural": "Alert: potential structural damage to buildings.",
        "severe": "Severe destruction warning: widespread heavy damage expected.",
        "catastrophic": "EMERGENCY BROADCAST: catastrophic event, evacuate now.",
    }
    return messages[category]


def parse_magnitude(value):
    magnitude = float(value)
    if magnitude < 0:
        raise ValueError("magnitude cannot be negative: %r" % (value,))
    return magnitude


def log(tremors):
    for raw in tremors:
        try:
            magnitude = parse_magnitude(raw)
        except (TypeError, ValueError):
            print("Invalid reading skipped: %r" % (raw,))
            continue
        category = classify(magnitude)
        print("Magnitude %.1f -> %s" % (magnitude, assessment(category)))


def summarize(tremors):
    counts = {}
    for raw in tremors:
        try:
            magnitude = parse_magnitude(raw)
        except (TypeError, ValueError):
            continue
        category = classify(magnitude)
        counts[category] = counts.get(category, 0) + 1
    return counts


def report(counts):
    if not counts:
        print("No valid readings to summarize.")
