    print("so the forest stays green while woody cones hold the seeds.")


def describe_willow():
    print("Willow: Its long branches droop toward the water like loose hair,")
    print("and children who sit beneath it swear the river answers back.")


def describe_birch():
    print("Birch: The papery white bark peels away in thin curling sheets,")
    print("which northern travellers once used as writing paper and canoe skin.")


def describe_sequoia():
    print("Sequoia: Taller than a thirty storey building and older than most")
    print("written history, a single trunk can weigh two thousand tonnes.")


def describe_cherry():
    print("Cherry: For a single spring week the branches vanish under pale pink")
    print("blossom, and then the petals fall like slow snow.")


def describe_palm():
    print("Palm: A tropical traveller of hot coasts, its crown of fronds shades")
    print("clusters of coconuts that drift across oceans to root on new sand.")


def describe_unknown(name):
    print("%s: Not on the official route, but every green thing here" % name)
    print("turns light into life, and that alone is worth a pause.")


TOURS = {
    "oak": describe_oak,
    "maple": describe_maple,
    "pine": describe_pine,
    "willow": describe_willow,
    "birch": describe_birch,
    "sequoia": describe_sequoia,
    "cherry": describe_cherry,
    "palm": describe_palm,
}


def normalize(name):
    return str(name).strip().lower()


def guide(stops):
    if not stops:
        print("The tour has no stops yet; add a species to begin.")
        return
    total = len(stops)
    for index, stop in enumerate(stops, 1):
        key = normalize(stop)
        print("Stop %d of %d: %s" % (index, total, key.title() or "Mystery"))
        handler = TOURS.get(key)
        if handler is None:
            describe_unknown(key.title() or "Unnamed specimen")
        else:
            handler()
        print("")
    known = [normalize(s) for s in stops if normalize(s) in TOURS]
    print("Walk complete: %d of %d stops were catalogued species." % (len(known), total))


if __name__ == "__main__":
