    "purl": "Purl: pull the yarn through the back of the loop.",
    "slip": "Slip: move the loop to the other needle without knitting it.",
    "increase": "Increase: create an extra loop on the needle.",
    "decrease": "Decrease: combine two loops into one.",
    "caston": "Cast on: add a starting loop to the needle.",
    "bindoff": "Bind off: finish the edge by casting the loop off.",
    "yarnover": "Yarn over: wrap the yarn around the needle.",
}

STITCH_DELTA = {
    "increase": 1,
    "caston": 1,
    "decrease": -1,
    "bindoff": -1,
    "yarnover": 1,
}


def normalize(code):
    if not isinstance(code, str):
        return None
    return code.strip().lower().replace(" ", "").replace("-", "")


def describe(code):
    key = normalize(code)
    if key is None or key not in INSTRUCTIONS:
        return None
    return INSTRUCTIONS[key]


def knit(stitches):
    if not stitches:
        print("Nothing to knit: the instruction list is empty.")
        return 0
    loops = 0
    for code in stitches:
        message = describe(code)
        if message is None:
            print("Unknown instruction code: %r (skipped)." % (code,))
            continue
        print(message)
        loops = loops + STITCH_DELTA.get(normalize(code), 0)
    return loops


def report(stitches, loops):
    known = [normalize(c) for c in stitches if describe(c) is not None]
    print("Worked %d of %d instructions." % (len(known), len(stitches)))
