    for key in known:
        counts[key] = counts.get(key, 0) + 1
    for key in sorted(counts):
        print("  %-9s x%d" % (key, counts[key]))
    if loops < 0:
        print("Warning: more loops were removed than created (%d)." % loops)
    else:
        print("Net change on the needle: %+d loop(s)." % loops)


