def normalize(codon):
    return str(codon).strip().lower()


def validate(codon):
    if codon in CONTROL_WORDS:
        return True
    if len(codon) != 3:
        print('Skipping %r: a codon must have exactly three letters.' % codon)
        return False
    for base in codon:
        if base not in VALID_BASES:
            print('Skipping %r: %r is not a nucleotide base.' % (codon, base))
            return False
    return True


def analyze(codons):
    tally = {}
    for raw in codons:
        codon = normalize(raw)
        if not validate(codon):
            continue
        if codon == 'start':
            print('START: sequence initiation detected.')
            label = 'initiation'
        elif codon == 'stop':
            print('STOP: sequence termination detected.')
            label = 'termination'
        elif codon == 'aaa':
            print('AAA codes for the amino acid lysine.')
            label = 'lysine'
        elif codon == 'ccc':
            print('CCC codes for the amino acid proline.')
            label = 'proline'
        elif codon == 'ggg':
            print('GGG codes for the amino acid glycine.')
            label = 'glycine'
        elif codon == 'ttt':
            print('TTT codes for the amino acid phenylalanine.')
            label = 'phenylalanine'
        elif codon[0] == 'a':
            print('%s is a mixed codon starting with a purine.' % codon.upper())
