def yield_time(index):
    print("Motion %d - YIELD: The member yields the remainder of their time to a colleague." % index)


def record_objection(index):
    print("Motion %d - OBJECT: Objection noted and entered formally into the minutes." % index)


def declare_recess(index):
    print("Motion %d - RECESS: This chamber stands in recess for a short break." % index)


