    print("Motion %d - VOTE: The question is called; all in favor say yea, opposed say nay." % index)


def amend_bill(index):
    print("Motion %d - AMEND: The bill before the chamber is hereby being modified." % index)


def table_discussion(index):
    print("Motion %d - TABLE: The current discussion is postponed indefinitely." % index)


HANDLERS = {
    "speak": grant_floor,
    "yield": yield_time,
    "object": record_objection,
    "recess": declare_recess,
    "adjourn": adjourn_session,
    "vote": call_vote,
    "amend": amend_bill,
    "table": table_discussion,
}


def moderate(motions):
    handled = 0
    rejected = []
    for index, raw in enumerate(motions, start=1):
        name = normalize(raw)
