def normalize(outcome):
    """Trim and lower-case a raw outcome so lookups are case-insensitive."""
    return outcome.strip().lower()


def runs_for(outcome):
    """Runs credited to the batting side for a single outcome."""
    table = {"dot": 0, "single": 1, "boundary": 4, "six": 6,
             "wide": 1, "noball": 1, "wicket": 0, "bye": 1}
    return table[outcome]


def is_legal(outcome):
    """Wides and no-balls do not count towards the six balls of an over."""
    return outcome not in ("wide", "noball")


def signal(outcome):
    """Speak the umpire's call for one delivery."""
    if outcome == "dot":
        print("Dot ball! No runs scored off that delivery.")
    elif outcome == "single":
        print("One run taken, the batsmen rotate the strike.")
    elif outcome == "boundary":
        print("Four runs! What a cracking shot through the gap!")
    elif outcome == "six":
        print("Six! The ball sails over the boundary rope and into the crowd.")
    elif outcome == "wide":
        print("Wide called: one extra run to the batting side.")
        print("Arms outstretched, an extra delivery must be bowled.")
    elif outcome == "noball":
        print("No ball! One run penalty against the bowling side.")
        print("Free hit coming up, the batsman cannot be bowled out.")
    elif outcome == "wicket":
        print("Howzat! A loud appeal rings around the ground.")
        print("Finger raised, the batsman walks off the field.")
    elif outcome == "bye":
        print("Bye signalled: runs scored without the bat touching the ball.")
    else:
        print("Unknown call '%s' ignored by the umpire." % outcome)


def umpire(deliveries):
    """Call every delivery in turn and report the state of the over."""
    total = 0
    wickets = 0
    legal_balls = 0
    for raw in deliveries:
        outcome = normalize(raw)
        signal(outcome)
