OPERATION_MESSAGES = {
    "load": "Insert the master tape into the playback deck.",
    "spool": "Wind the blank magnetic tape onto the supply reel.",
    "record": "Transfer the audio signal to the blank tape at high speed.",
    "verify": "Check the audio quality of the duplicated tape.",
    "cut": "Slice the tape to the correct length for the running time.",
    "splice": "Join the tape to the leader with splicing tape.",
    "shell": "Enclose the tape in the plastic cassette housing.",
    "label": "Stamp the album artwork onto the cassette label.",
}

STEP_ORDER = ["load", "spool", "record", "verify", "cut", "splice", "shell", "label"]


def normalize(step):
    """Return the canonical operation code for a raw entry."""
    return str(step).strip().lower()


def duplicate(steps):
    """Run each machine operation code in order, printing its instruction."""
    for raw in steps:
        code = normalize(raw)
        if code in OPERATION_MESSAGES:
            print(OPERATION_MESSAGES[code])
        else:
            print("Unknown operation code: %s" % code)


def missing_steps(steps):
    """List canonical operations that never appear in the given sequence."""
    seen = set()
    for raw in steps:
        seen.add(normalize(raw))
    return [code for code in STEP_ORDER if code not in seen]


def report(steps):
    """Print a short summary of a duplication run, then perform it."""
    codes = [normalize(raw) for raw in steps]
    print("Duplication run: %d operation(s) queued." % len(codes))
    print("Sequence: %s" % ", ".join(codes))
    duplicate(steps)
    absent = missing_steps(steps)
    if absent:
        print("Skipped operations: %s" % ", ".join(absent))
    else:
        print("Full duplication cycle completed.")


def main():
    print("=== Cassette duplication machine ===")
    report(["load", "record"])
    print("")
    print("--- Second run ---")
    report(STEP_ORDER)
    print("")
    print("--- Operator typo run ---")
    report([" LOAD ", "rewind", "label"])


if __name__ == "__main__":
    main()

