def normalize(instruction):
    """Strip surrounding whitespace and lowercase a raw waypoint instruction."""
    return instruction.strip().lower()


def describe(step):
    """Return the message for a known instruction, or None if unrecognised."""
    messages = {
        "north": "Walk towards the magnetic pole.",
        "south": "Head towards the equator.",
        "east": "Walk towards the sunrise.",
        "west": "Head towards the sunset.",
        "search": "Look under rocks and logs.",
        "find": "Hooray! You located the hidden container!",
        "sign": "Write your name in the logbook.",
        "trade": "Swap a small trinket for another.",
    }
    return messages.get(step)


def navigate(waypoints):
    """Print the treasure hunt message for each instruction in waypoints."""
    if isinstance(waypoints, str):
        raise TypeError("navigate expects a list of instructions, not a string")
    followed = []
    for index, raw in enumerate(waypoints, 1):
        step = normalize(raw)
        message = describe(step)
        if message is None:
            print("Waypoint %d: unknown instruction %r - skipping." % (index, raw))
            continue
        print("Waypoint %d: %s" % (index, message))
        followed.append(step)
    return followed


def summarize(followed):
    """Print a short report about the walk that was just completed."""
    moves = [step for step in followed if step in ("north", "south", "east", "west")]
    print("Followed %d of the waypoints." % len(followed))
    if moves:
        print("Compass legs walked: %s" % ", ".join(moves))
    else:
        print("You never moved from the trailhead.")
    if "find" in followed:
        print("The container was found on this trip.")
    else:
        print("The container is still hidden somewhere out there.")
    if "sign" in followed and "find" not in followed:
        print("Odd: you signed a logbook you never opened.")
    if "trade" in followed:
        print("Remember to note the trade in the logbook too.")


def main():
    short_hunt = ["north", "search"]
    print("--- Short hunt ---")
    summarize(navigate(short_hunt))
    full_hunt = [" North ", "east", "SEARCH", "dig", "find", "sign", "trade", "west"]
    print("--- Full hunt ---")
    summarize(navigate(full_hunt))
    try:
        navigate("north")
    except TypeError as error:
        print("Rejected bad input: %s" % error)


if __name__ == "__main__":
    main()

