TOLL_RATES = {
    "car": 2,
    "motorcycle": 1,
    "truck": 5,
    "bus": 4,
    "emergency": 0,
    "military": 0,
    "exempt": 0,
}


def normalize(vehicle):
    return str(vehicle).strip().lower()


def process(vehicles):
    revenue = 0
    for vehicle in vehicles:
        kind = normalize(vehicle)
        if kind == "car":
            revenue += TOLL_RATES["car"]
            print("Standard toll collected. Daily revenue: %d" % revenue)
        elif kind == "motorcycle":
            revenue += TOLL_RATES["motorcycle"]
            print("Discounted toll for motorcycle. Daily revenue: %d" % revenue)
        elif kind == "truck":
            revenue += TOLL_RATES["truck"]
            print("Heavy duty vehicle surcharge applied. Daily revenue: %d" % revenue)
        elif kind == "bus":
            revenue += TOLL_RATES["bus"]
            print("Passenger transport fare collected. Daily revenue: %d" % revenue)
        elif kind == "emergency":
            print("Emergency vehicle: raising the barrier immediately.")
        elif kind == "military":
            print("Official convoy cleared through the lane.")
        elif kind == "exempt":
            print("Government vehicle pass accepted, no charge.")
        elif kind == "violation":
            print("Flashing camera to capture the license plate.")
        else:
            print("Unrecognized vehicle type at the gate: %s" % kind)
    return revenue


def count_types(vehicles):
    counts = {}
    for vehicle in vehicles:
        kind = normalize(vehicle)
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def report(vehicles, revenue):
    print("--- End of shift report ---")
    print("Vehicles handled: %d" % len(vehicles))
    counts = count_types(vehicles)
    for kind in sorted(counts):
        print("  %-11s x%d" % (kind, counts[kind]))
    exempt_total = sum(counts.get(k, 0) for k in ("emergency", "military", "exempt"))
    if exempt_total:
        print("Free passages granted: %d" % exempt_total)
    if "violation" in counts:
        print("Plates photographed for follow-up: %d" % counts["violation"])
    print("Total daily revenue: %d" % revenue)


def main():
    lane = [
        "car", "motorcycle", "truck", "bus", "emergency",
        "military", "exempt", "violation", "car", "Tractor",
    ]
    total = process(lane)
    report(lane, total)


if __name__ == "__main__":
    main()

