CUES = {
    "mountain": "Mountain: stand tall, feet together, and breathe deeply.",
    "downward": "Downward Dog: press your hips up and back, heels toward the floor.",
    "plank": "Plank: hold your body in one straight line from head to heels.",
    "chaturanga": "Chaturanga: lower down slowly, elbows hugging your ribs.",
    "cobra": "Cobra: lift your chest and look forward, shoulders relaxed.",
    "child": "Child's Pose: rest and sit back on your heels, forehead down.",
    "tree": "Tree: find your balance and lift one foot to the inner thigh.",
    "corpse": "Corpse Pose: lie flat on your back and relax completely.",
}

ORDER = ["mountain", "downward", "plank", "chaturanga", "cobra", "child",
         "tree", "corpse"]


def normalize(name):
    cleaned = name.strip().lower()
    for suffix in (" pose", " dog", "'s pose"):
        if cleaned.endswith(suffix):
            cleaned = cleaned[:-len(suffix)].strip()
    return cleaned


def cue_for(name):
    return CUES.get(normalize(name))


def instruct(poses):
    if isinstance(poses, str):
        poses = [poses]
    recognized = []
    for pose in poses:
        cue = cue_for(pose)
        if cue is None:
            print("I don't have a cue for '%s' yet." % pose)
        else:
            print(cue)
            recognized.append(normalize(pose))
    return recognized


def report(recognized):
    print("--- Session summary ---")
    if not recognized:
        print("No poses were practised.")
        return
    counts = {}
    for pose in recognized:
        counts[pose] = counts.get(pose, 0) + 1
    for pose in ORDER:
        if pose in counts:
            print("%-12s x%d" % (pose, counts[pose]))
    print("Total poses held: %d" % len(recognized))


def full_sequence():
    print("Running the full sequence:")
    return instruct(ORDER)


def main():
    print("Quick flow:")
    done = instruct(["plank", "tree"])
    report(done)
    print("")
    done = instruct(["Downward Dog", "Child's Pose", "handstand"])
    report(done)
    print("")
    report(full_sequence())


