    print("Old rubber rolls away, fresh slicks slotted onto the hubs.")
    print("BZZZT! Nuts torqued down, gunner raises a hand: wheel on!")


def refuel(task):
    litres = parse_amount(task)
    print("--- %s ---" % task.upper())
