text_nat:
SPEED = 25.0

SEVERITY_WORDS = {
    1: "hairpin",
    2: "very tight",
    3: "tight",
    4: "medium",
    5: "fast",
    6: "flat out",
}


def check_curves(curves):
    if not curves:
        raise ValueError("a rally stage needs at least one curve")
    for index, curve in enumerate(curves):
        if len(curve) != 3:
            raise ValueError("curve %d must have distance, direction, severity" % (index + 1))
        distance, direction, severity = curve
        if distance <= 0:
            raise ValueError("curve %d has a non-positive distance" % (index + 1))
        if severity not in SEVERITY_WORDS:
            raise ValueError("curve %d has severity outside one to six" % (index + 1))


def start_countdown():
    for number in (5, 4, 3, 2, 1):
        print("%d..." % number)
    print("Go, go, go!")


def call_turn(distance, direction, severity):
    print("%d meters" % distance)
    print("%s %d - %s" % (direction, severity, SEVERITY_WORDS[severity]))
    if severity >= 5:
        print("Caution! Do not lift, but stay off the banking!")
    if "water splash" in direction.lower():
        print("Water splash coming - wipers on!")


def format_time(seconds):
    minutes = int(seconds) // 60
    remainder = seconds - minutes * 60
    return "%d:%04.1f" % (minutes, remainder)


def navigate(curves):
    check_curves(curves)
    start_countdown()
    print("Transmission engaged, notes running.")
    total_distance = 0
    for index, curve in enumerate(curves):
        distance, direction, severity = curve
        call_turn(distance, direction, severity)
        total_distance += distance
        if index + 1 < len(curves) and curves[index + 1][0] < 50:
            print("into")
    print("Flying finish!")
    print("Stop control reached, engine off.")
    print("Stage time: %s" % format_time(total_distance / SPEED))
    return total_distance


def main():
    stage = [
        (50, "left", 4),
        (30, "right into water splash", 5),
        (200, "left over crest", 6),
        (40, "right", 2),
        (120, "left", 3),
    ]
    covered = navigate(stage)
    print("Stage length: %d meters over %d calls." % (covered, len(stage)))


if __name__ == "__main__":
    main()

