def normalize_result(result):
    cleaned = str(result).strip().lower()
    if cleaned not in ("goal", "save", "miss"):
        raise ValueError("unknown shot result: %s" % result)
    return cleaned


def validate_attempts(attempts):
    if not attempts:
        raise ValueError("a shootout needs at least one attempt")
    checked = []
    for entry in attempts:
        if len(entry) != 3:
            raise ValueError("each attempt needs team, jersey and result")
        team, jersey, result = entry
        checked.append((str(team), int(jersey), normalize_result(result)))
    return checked


def describe_result(team, jersey, result):
    if result == "goal":
        print("The puck rips past the blocker and buries itself in the top corner!")
        print("GOAL for %s! Number %d celebrates at center ice." % (team, jersey))
    elif result == "save":
        print("A miraculous save! The goaltender's glove swallows the puck.")
        print("Number %d of %s drops to a knee in disbelief." % (jersey, team))
    else:
        print("Off the post and wide - a heartbreaking miss.")
        print("Number %d of %s stares at the iron that betrayed them." % (jersey, team))


def format_score(tally):
    parts = []
    for team in sorted(tally):
        parts.append("%s %d" % (team, tally[team]))
    return " - ".join(parts)


def pick_winner(tally):
    best = max(tally.values())
    leaders = [team for team in sorted(tally) if tally[team] == best]
    return leaders


def shootout(attempts):
    plays = validate_attempts(attempts)
    print("The shootout begins! Both benches are on their feet.")
    print("The crowd is roaring so loudly the boards are shaking.")
    tally = {}
    for team, jersey, result in plays:
        tally.setdefault(team, 0)
    for index, play in enumerate(plays):
        team, jersey, result = play
        print("--- Round %d ---" % (index + 1))
        print("Number %d of %s steps up to center ice." % (jersey, team))
        describe_result(team, jersey, result)
        if result == "goal":
            tally[team] += 1
        print("Score: %s" % format_score(tally))
    leaders = pick_winner(tally)
    if len(leaders) > 1:
        print("Still deadlocked at %s - nobody can separate them." % format_score(tally))
    else:
        print("%s wins the shootout!" % leaders[0])
        print("The players pour off the bench and rush the ice in celebration.")
    return tally


def main():
    attempts = [
        ("Home Team", 19, "goal"),
        ("Visitors", 7, "save"),
        ("Home Team", 44, "miss"),
        ("Visitors", 11, "miss"),
    ]
    final = shootout(attempts)
    print("Final tally: %s" % format_score(final))


if __name__ == "__main__":
    main()

