def classify(severity):
    if severity <= 3:
        return "low"
    if severity <= 7:
        return "medium"
    return "high"


def validate(hits):
    clean = []
    for index, hit in enumerate(hits):
        if len(hit) != 3:
            print("Skipping malformed hit at position %d" % index)
            continue
        attacker, victim, severity = hit
        if severity < 1 or severity > 10:
            print("Severity %s out of range for car %s, clamping" % (severity, attacker))
            severity = max(1, min(10, severity))
        clean.append((attacker, victim, severity))
    return clean


def describe(attacker, victim, severity):
    level = classify(severity)
    print("Car #%s slams into car #%s at severity %d!" % (attacker, victim, severity))
    if level == "low":
        print("Just a fender bender, paint traded and nothing more.")
    elif level == "medium":
        print("A solid crunch! Sheet metal folds and the crowd howls.")
    else:
        print("Catastrophic smash! The whole front end disintegrates.")
    return level


def roster(hits):
    cars = []
    for attacker, victim, severity in hits:
        for car in (attacker, victim):
            if car not in cars:
                cars.append(car)
    return cars


def derby(hits):
    hits = validate(hits)
    cars = roster(hits)
    eliminated = []
    print("The green flag drops!")
    print("Engines roar and the field surges forward in a cloud of dust.")
    for attacker, victim, severity in hits:
        if victim in eliminated:
            print("Car #%s pounds the dead wreck of car #%s for nothing." % (attacker, victim))
            continue
        level = describe(attacker, victim, severity)
        if level == "high":
            eliminated.append(victim)
            print("Car #%s is eliminated and hauled off the infield!" % victim)
    print("The checkered flag waves over the carnage.")
    print("The smoke settles across the churned-up mud.")
    survivors = [car for car in cars if car not in eliminated]
    if not survivors:
        print("Total annihilation: nobody is left to take the trophy.")
        return None
    champion = survivors[-1]
    for car in survivors[:-1]:
        print("Car #%s limps away, battered but breathing." % car)
    print("Car #%s is the last car standing and your champion!" % champion)
    return champion


def main():
    hits = [(7, 42, 8), (42, 7, 3), (7, 13, 5), (13, 7, 10), (13, 42, 6)]
    champion = derby(hits)
    print("Official result: car #%s" % champion)


if __name__ == "__main__":
    main()

