text_nat:
def validate_course(course):
    """Return a cleaned list of (name, difficulty) pairs, rejecting bad entries."""
    cleaned = []
    for entry in course:
        if len(entry) != 2:
            raise ValueError("each obstacle needs a name and a difficulty")
        name, difficulty = entry
        difficulty = int(difficulty)
        if difficulty < 1 or difficulty > 5:
            raise ValueError("difficulty out of range for %s" % name)
        cleaned.append((str(name).strip(), difficulty))
    return cleaned


def start_race(count):
    print("The starting horn blares across the field!")
    print("The participant whoops and cheers, fists in the air!")
    print("Splash! The first muddy plunge soaks them head to toe.")
    print("%d obstacles stand between them and the medal." % count)


def approach(name, difficulty):
    stars = "*" * difficulty
    print("Approaching the %s (%s)..." % (name, stars))


def tackle(name, difficulty):
    if difficulty >= 4:
        print("Muscles burn on the %s - every inch is a fight!" % name)
        print("Teammates grab an arm and haul them over together.")
    else:
        print("A smooth, confident crossing of the %s." % name)
    if name.lower() == "ice bath":
        print("BRAIN FREEZE WARNING: the cold bites straight to the skull!")


def finish_race(hardest):
    print("They stagger across the finish line, caked in mud!")
    print("Exhaustion hits: legs shaking, lungs heaving, grin enormous.")
    print("The %s was the toughest test of the day." % hardest)
    print("A medal is placed around their neck. Race complete!")


def mudrun(course):
    obstacles = validate_course(course)
    start_race(len(obstacles))
    hardest = obstacles[0][0]
    toughest_rating = 0
    for name, difficulty in obstacles:
        approach(name, difficulty)
        tackle(name, difficulty)
        if difficulty > toughest_rating:
            toughest_rating = difficulty
            hardest = name
    finish_race(hardest)
    return len(obstacles)


