        return "landed with a small check of the shoulders"
    if score == -1:
        return "a wobble on the landing, but the edge holds"
    return "a hand down on the ice, that will cost some points"


def classify(name):
    lowered = name.lower()
    if "spin" in lowered:
        return "spin"
    if "sequence" in lowered or "steps" in lowered:
        return "steps"
    for word in JUMP_WORDS:
        if word in lowered:
            return "jump"
    return "other"


def announce_jump(name, score):
    parts = [part.strip() for part in name.split("+")]
    counts = [rotation_count(part) for part in parts]
    print("%s! %d revolutions in the air." % (name.title(), sum(counts)))
    if len(parts) > 1:
