    print("The skater glides to center ice and settles into the starting pose.")
    print("The music begins.")
    for name, score in elements:
        kind = classify(name)
        if kind == "jump":
            announce_jump(name, score)
        elif kind == "spin":
            announce_spin(name, score)
        elif kind == "steps":
            announce_steps(name, score)
        else:
            print("%s, graded at %+d." % (name.title(), score))
    print("A final dramatic pose, arms thrown wide as the last note fades.")
    print("The audience erupts in applause and flowers rain onto the ice.")
    print("Now to the kiss and cry, waiting for the score.")


def main():
    routine = [
        ("triple axel", 2),
        ("triple lutz + triple toe loop", 1),
        ("layback spin", 0),
        ("step sequence", 2),
    ]
    skate(routine)


if __name__ == "__main__":
