def validate_gates(gates):
    if not isinstance(gates, list):
        raise TypeError("gates must be a list of three item tuples")
    checked = []
    for entry in gates:
        if len(entry) != 3:
            raise ValueError("each gate needs a number, a color and a penalty")
        number, color, penalty = entry
        color = str(color).lower()
        if color not in ("green", "red"):
            raise ValueError("unknown pole color: %s" % color)
        if penalty < 0:
            raise ValueError("penalty seconds cannot be negative")
        checked.append((number, color, penalty))
    return checked


def announce_start(total_gates):
    print("The whistle blows across the canyon!")
    print("The kayaker slices through the start beam.")
    print("Three aggressive strokes drive the boat into the current.")
    print("Course ahead: %d gates." % total_gates)


def run_green_gate(number):
    print("Gate %d (green): riding the downstream flow, bow aimed straight." % number)
    print("Clean downstream line through gate %d." % number)


def run_red_gate(number):
    print("Gate %d (red): hard eddy turn to attack the gate upstream." % number)
    print("Fighting the current, the stern swings clear of gate %d." % number)


def report_touch(number, penalty):
    print("Pole touch at gate %d! %d penalty second(s) added." % (number, penalty))


def paddle_between(next_number):
    print("Smooth paddling section, breathing before gate %d." % next_number)


def announce_finish(total_penalty):
    print("The kayaker crosses the finish line!")
    print("The paddle is tossed high in celebration.")
    print("Total penalty time: %d second(s)." % total_penalty)


def slalom(gates):
    course = validate_gates(gates)
    announce_start(len(course))
    total_penalty = 0
    for index, gate in enumerate(course):
        number, color, penalty = gate
        if color == "green":
            run_green_gate(number)
        else:
            run_red_gate(number)
        if penalty > 0:
            report_touch(number, penalty)
            total_penalty += penalty
        if index + 1 < len(course):
            paddle_between(course[index + 1][0])
    announce_finish(total_penalty)
    return total_penalty


def main():
    course = [(1, "green", 0), (2, "red", 2), (3, "green", 0), (4, "red", 50)]
    penalty = slalom(course)
    if penalty >= 50:
        print("A gate was missed, the run is out of medal contention.")
    else:
        print("A tidy run with only %d second(s) lost." % penalty)


if __name__ == "__main__":
    main()

