import random

RED_NUMBERS = set([1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36])


def color_of(number):
    if number == 0:
        return "green"
    if number in RED_NUMBERS:
        return "red"
    return "black"


def normalize_bet(bet):
    name, choice, amount = bet
    wager = float(amount)
    if wager <= 0:
        raise ValueError("%s placed a non-positive wager" % name)
    token = str(choice).strip().lower()
    if token.isdigit():
        pocket = int(token)
        if pocket < 0 or pocket > 36:
            raise ValueError("%s bet on invalid pocket %s" % (name, token))
        return (name, "number", pocket, wager)
    if token in ("red", "black"):
        return (name, "color", token, wager)
    raise ValueError("%s bet on unknown option %s" % (name, choice))


def resolve(bet, number, color):
    kind, target, wager = bet[1], bet[2], bet[3]
    if kind == "number" and target == number:
        return wager * 35
    if kind == "color" and target == color:
        return wager
    return 0.0


def roulette(bets):
    table = [normalize_bet(bet) for bet in bets]
    print("The dealer clears the table of old markers and dust.")
    print("Chips clatter as the dealer shuffles the stacks into neat columns.")
    for name, kind, target, wager in table:
        print("%s places $%.2f on %s." % (name, wager, target))
    print("NO MORE BETS!")
    print("The wheel spins, mahogany blurring into a single ring of light.")
    print("The ivory ball races the rim, then drops and bounces across the wooden pockets.")
    number = random.randint(0, 36)
    color = color_of(number)
    print("%d %s! The ball rests in %d %s!" % (number, color.upper(), number, color))
    results = []
    for bet in table:
        payout = resolve(bet, number, color)
        name, wager = bet[0], bet[3]
        if payout > 0:
            print("Congratulations %s, you win $%.2f!" % (name, payout))
            print("The dealer pushes a tall stack of chips forward to %s." % name)
        else:
            print("Sorry %s, the house collects your $%.2f." % (name, wager))
            print("The rake sweeps the board clean where %s had hoped." % name)
        results.append((name, payout - wager))
    total = sum(net for name, net in results)
    print("Table summary:")
    for name, net in results:
        print("  %-10s %+.2f" % (name, net))
    print("Net swing for the players: %+.2f" % total)
    return results


def main():
    bets = [
        ("Alice", "red", 50),
        ("Bob", "17", 20),
        ("Cleo", "black", 75),
    ]
    roulette(bets)
    print("The dealer waits for the next round of wagers.")


if __name__ == "__main__":
    main()

