def format_weight(grams):
    if grams >= 1000:
        return "%.2f kg" % (grams / 1000.0)
    return "%d g" % grams


def age_note(age):
    notes = {
        "juvenile": "soft downy edges on the wing coverts",
        "adult": "crisp, fully moulted plumage",
        "subadult": "a mix of old and fresh feathers",
    }
    return notes.get(age.lower(), "feather wear that resists easy reading")


def make_band_code(index, species):
    initials = "".join([part[0] for part in species.split()]).upper()
    return "%s-%05d" % (initials, 1000 + index)


def open_nets():
    print("Dawn at the station: the mist nets are unfurled between the poles.")
    print("The panels are checked for snags and the guy lines pulled taut.")
    print("Now the quiet waiting begins; only the kettle and the wind speak.")


def close_nets(count, total_weight):
    print("The last round is walked and the mist nets are furled and closed.")
    print("Birds handled today: %d" % count)
    if count:
        print("Mean mass of today's captures: %s" % format_weight(total_weight / float(count)))
    else:
        print("No captures today; the log will record effort without birds.")
    print("Data entry begins: ring numbers, masses and ages go into the ledger.")


def band(birds):
    if not isinstance(birds, (list, tuple)):
        raise TypeError("band() expects a list of (species, weight, age) tuples")
    open_nets()
    total_weight = 0.0
    handled = 0
    for index, record in enumerate(birds):
        if len(record) != 3:
            raise ValueError("each record needs species, weight and age")
        species, weight, age = record
        print("-" * 52)
        print("A flutter in panel three: gently untangling the fine mesh.")
        print("The bird is eased out head first and cupped in a ringer's grip.")
        print("Species identified: %s" % species)
        code = make_band_code(index, species)
        print("Numbered metal leg band %s closed around the tarsus." % code)
        print("Band seated smoothly; it spins free without pinching.")
        print("Mass on the balance: %s" % format_weight(weight))
        print("Blowing softly on the breast feathers to read the age.")
        print("Estimated age %s, confirmed by %s." % (age, age_note(age)))
        print("Hands opened: the %s bursts away over the hedge. Fly well!" % species)
        total_weight += weight
        handled += 1
    print("=" * 52)
    close_nets(handled, total_weight)
    return handled


def main():
    catch = [
        ("robin", 70, "adult"),
        ("blue tit", 11, "juvenile"),
        ("song thrush", 83, "subadult"),
    ]
    ringed = band(catch)
    print("Station summary filed for %d ringed birds." % ringed)


if __name__ == "__main__":
    main()

