def burnout():
    print("Water box flooded - rear tires spinning up")
    print("Tire smoke boils off the slicks, rubber laid down")
    print("Rolling forward, careful staging - pre-stage bulb lit")
    print("Deep stage locked in, both bulbs glowing")


def countdown():
    for bulb in ("first", "second", "third"):
        print("Yellow bulb drops - %s amber" % bulb)
    print("GREEN LIGHT! The car launches off the line")


def rpm_for(speed):
    return 2000 + int(speed) * 38


def gear_for(speed):
    if speed < 60:
        return 1
    if speed < 110:
        return 2
    if speed < 160:
        return 3
    return 4


def elapsed_time(distance, speed):
    if speed <= 0:
        return 0.0
    return round(distance / (speed * 1.4667), 3)


def report_stage(marker, speed):
    rpm = rpm_for(speed)
    gear = gear_for(speed)
