def validate_parts(parts):
    if not isinstance(parts, (list, tuple)):
        raise TypeError("parts must be a list of (panel, method) tuples")
    checked = []
    for entry in parts:
        if len(entry) != 2:
            raise ValueError("each part needs a panel name and a joinery method")
        name, method = entry
        checked.append((str(name).strip(), str(method).strip().lower()))
    return checked


def unpack_flat_box(parts):
    print("Slicing the tape and unpacking the flat box on the floor.")
    print("Inventory check: %d panels and a bag of hardware accounted for." % len(parts))
    print("Clearing the workspace so every panel has room to lie flat.")


def align_edges(name):
    print("Aligning the wooden edges of the %s until the seam is flush." % name)


def apply_wood_glue(name):
    print("Running an even bead of wood glue along the %s joint." % name)
    print("Clamping the %s and letting it sit for twenty minutes." % name)


def drive_pocket_screws(name):
    print("Drilling pocket holes into the back face of the %s." % name)
    print("Driving the pocket screws home for a snug, gap free fit.")


def unknown_method(name, method):
    print("No technique on file for '%s' on the %s; consult the plan." % (method, name))


def build_part(name, method):
    align_edges(name)
    if method == "wood glue":
        apply_wood_glue(name)
    elif method == "pocket screws":
        drive_pocket_screws(name)
    else:
        unknown_method(name, method)


def attach_hinges():
    print("Attaching the swinging door hinges and testing the swing.")


def apply_finish():
    print("Wiping on a coat of finishing oil with a lint free rag.")
    print("Buffing the surface until the grain glows.")
    print("The build is complete: the cabinet is ready for the room.")


def cabinet(parts):
    checked = validate_parts(parts)
    unpack_flat_box(checked)
    for name, method in checked:
        build_part(name, method)
    attach_hinges()
    apply_finish()
    return len(checked)


def main():
