def validate(pieces):
    if not pieces:
        raise ValueError("no leather sections supplied")
    checked = []
    for section, ounces in pieces:
        name = str(section).strip()
        if not name:
            raise ValueError("a leather section is missing its name")
        weight = float(ounces)
        if weight <= 0:
            raise ValueError("thickness must be positive for %s" % name)
        checked.append((name, weight))
    return checked


def prepare_hide(pieces):
    print("Rolling out the premium hide across the workbench.")
    print("Inspecting the grain for scars, stretch and tight fibre.")
    total = 0.0
    for name, weight in pieces:
        print("Tracing the precise pattern for the %s." % name)
        total = total + weight
    return total


def cut_piece(name, weight):
    print("The sharp blade cuts the shape of the %s." % name)
    if weight > 4:
        print("Note: extra pressure on the skiving knife to thin the %s edges." % name)
        return True
    return False


def stitch(pieces):
    holes = 0
    for name, weight in pieces:
        spacing = 6 if weight > 4 else 8
        print("Hammering the pricking irons along the %s at %d holes per inch." % (name, spacing))
        holes = holes + spacing
    print("Rhythmic figure eight saddle stitching with waxed thread pulls the seams tight.")
    return holes


def finish(pieces):
    for name, _ in pieces:
        print("Burnishing the edges of the %s until they gleam." % name)
    print("Rubbing beeswax into the grain and buffing it warm by hand.")
    print("Final inspection: every stitch even, every edge slick.")


def leather(pieces):
    checked = validate(pieces)
    total = prepare_hide(checked)
    skived = 0
    for name, weight in checked:
        if cut_piece(name, weight):
            skived = skived + 1
    holes = stitch(checked)
    finish(checked)
    print("Assembled %d sections totalling %.1f ounces of leather." % (len(checked), total))
    print("Pricking iron work produced %d stitching holes." % holes)
    if skived:
        print("%d section(s) required skiving to reduce bulk." % skived)
    return {"sections": len(checked), "ounces": total, "holes": holes, "skived": skived}


