text_nat:
ACTION_PHRASES = {
    'parry': '%s deflects the incoming blade with a crisp parry',
    'riposte': '%s answers instantly with a lightning riposte',
    'lunge': '%s drives forward in a deep lunge',
}

LIGHT_COLORS = {'left': 'red', 'right': 'green'}


def normalize_fencer(fencer):
    name = str(fencer).strip().lower()
    if name not in LIGHT_COLORS:
        raise ValueError('unknown fencer: %s' % fencer)
    return name


def describe_action(fencer, action):
    key = str(action).strip().lower()
    if key not in ACTION_PHRASES:
        raise ValueError('unknown blade action: %s' % action)
    return ACTION_PHRASES[key] % fencer.capitalize()


def format_score(scores):
    return 'Left %d - %d Right' % (scores['left'], scores['right'])


def salute():
    print('Salute! The fencers honour each other and the referee.')
    print('Masks down, blades up.')
    print('En garde... Ready... Fence!')


def fencing(touches):
    salute()
    scores = {'left': 0, 'right': 0}
    for touch in touches:
        fencer, action, valid = touch
        fencer = normalize_fencer(fencer)
        print(describe_action(fencer, action) + '.')
        if valid:
            scores[fencer] += 1
            print('Touch! Point awarded to the %s fencer.' % fencer)
            print('The %s light flashes on the scoring box.' % LIGHT_COLORS[fencer])
            print('Score is now %s.' % format_score(scores))
        else:
            print('Halt! The hit landed off target.')
            print('A white light shows on the box.')
            print('No point is given.')
    announce_result(scores)
    return scores


def announce_result(scores):
    if scores['left'] > scores['right']:
        print('Match point to the left fencer!')
    elif scores['right'] > scores['left']:
        print('Match point to the right fencer!')
    else:
        print('The bout ends level, no match point awarded.')
    print('Final score: %s.' % format_score(scores))
    print('Masks off, handshake exchanged. The bout is over.')


def main():
    touches = [
        ('left', 'lunge', True),
        ('right', 'parry', False),
        ('right', 'riposte', True),
        ('left', 'lunge', False),
        ('left', 'riposte', True),
    ]
    scores = fencing(touches)
    total = scores['left'] + scores['right']
    print('Valid touches recorded in this bout: %d.' % total)


if __name__ == '__main__':
    main()

