def normalize_url(url):
    """Trim whitespace and add a scheme if the caller omitted it."""
    cleaned = url.strip()
    if not cleaned:
        raise ValueError("url must not be empty")
    if "://" not in cleaned:
        print("no scheme given, assuming http:// for", cleaned)
        cleaned = "http://" + cleaned
    return cleaned


def split_url(url):
    """Return (scheme, host, path) for an already normalized url."""
    scheme, remainder = url.split("://", 1)
    if "/" in remainder:
        host, path = remainder.split("/", 1)
        path = "/" + path
    else:
        host, path = remainder, "/"
    if not host:
        raise ValueError("url has no host: " + url)
    return scheme.lower(), host.lower(), path


def check_website_status(url):
    """Pretend to perform an HTTP request and report the resulting status."""
    target = normalize_url(url)
    scheme, host, path = split_url(target)
    print("connecting to", host, "over", scheme)
    print("requesting", path)
    status = "200 OK"
    print("server replied:", status)
    return status


def status_code(status):
    """Extract the numeric part of a status line such as '200 OK'."""
    return int(status.split(" ", 1)[0])


def check_many(urls):
    """Check several sites, collecting results and errors in one mapping."""
    results = {}
    for url in urls:
        try:
            results[url] = check_website_status(url)
        except ValueError as exc:
            print("skipping invalid entry:", exc)
            results[url] = "000 INVALID"
    return results


def report(results):
    """Print a human readable summary and return the number of healthy sites."""
    healthy = 0
    for url, status in results.items():
        code = status_code(status)
        mark = "ok" if code == 200 else "fail"
        print("{:<28} {:>12}  [{}]".format(url, status, mark))
        if code == 200:
            healthy += 1
    print("healthy:", healthy, "of", len(results))
    return healthy


def main():
    sites = [
        "http://example.com",
        "https://google.com",
        "example.org/status",
        "   ",
    ]
    results = check_many(sites)
    print("-" * 48)
    healthy = report(results)
    if healthy == len(results):
        print("all monitored sites are up")
    else:
        print("some entries need attention")


if __name__ == "__main__":
    main()

