def validate_matrix(matrix):
    """Raise ValueError/TypeError if matrix is not a rectangular 2D numeric matrix."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    if not matrix:
        return 0, 0
    widths = set()
    for row in matrix:
        if not isinstance(row, list):
            raise TypeError("each row of matrix must be a list")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("matrix entries must be int or float")
        widths.add(len(row))
    if len(widths) > 1:
        raise ValueError("matrix rows must all have the same length")
    return len(matrix), widths.pop()


def transpose_matrix(matrix):
    """Return the transpose of a rectangular 2D matrix as a new list of lists."""
    rows, cols = validate_matrix(matrix)
    return [[matrix[r][c] for r in range(rows)] for c in range(cols)]


def format_matrix(matrix):
    """Render a matrix as aligned text lines."""
    if not matrix:
        return "(empty)"
    cells = [[str(value) for value in row] for row in matrix]
    width = max([len(text) for row in cells for text in row] + [0])
    return "\n".join(" ".join(text.rjust(width) for text in row) for row in cells)


def report(matrix):
    """Print a matrix, its transpose and the shape change."""
    rows, cols = validate_matrix(matrix)
    result = transpose_matrix(matrix)
    print("original ({0}x{1}):".format(rows, cols))
    print(format_matrix(matrix))
    print("transposed ({0}x{1}):".format(cols, rows))
    print(format_matrix(result))
    if result and transpose_matrix(result) == matrix:
        print("double transpose restores the original")
    print("-" * 32)
    return result


def main():
    print(transpose_matrix([[1, 2, 3], [4, 5, 6]]))
    print(transpose_matrix([[10]]))
    print("=" * 32)

    samples = [
        [[1, 2, 3], [4, 5, 6]],
        [[10]],
        [[1.5, -2.0], [0.25, 4.0], [7.0, 8.5]],
        [],
    ]
    for sample in samples:
        report(sample)

    bad_inputs = [[[1, 2], [3]], [[1, "x"]], "not a matrix"]
    for bad in bad_inputs:
        try:
            transpose_matrix(bad)
        except (TypeError, ValueError) as exc:
            print("rejected {0!r}: {1}".format(bad, exc))


if __name__ == "__main__":
    main()

