def update_inventory(inventory, item_name, quantity_change):
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(item_name, str) or not item_name:
        raise ValueError("item_name must be a non-empty string")
    if not isinstance(quantity_change, int) or isinstance(quantity_change, bool):
        raise TypeError("quantity_change must be an integer")

    current = inventory.get(item_name, 0)
    new_quantity = current + quantity_change
    if new_quantity < 0:
        new_quantity = 0
    inventory[item_name] = new_quantity
    return inventory


def format_line(item_name, quantity):
    status = "OUT OF STOCK" if quantity == 0 else "low" if quantity < 5 else "ok"
    return "{:<12} {:>4}  {}".format(item_name, quantity, status)


def show_inventory(inventory, title):
    print(title)
    print("-" * len(title))
    for item_name in sorted(inventory):
        print(format_line(item_name, inventory[item_name]))
    print("total units:", sum(inventory.values()))


def apply_transactions(inventory, transactions):
    for item_name, quantity_change in transactions:
        before = inventory.get(item_name, 0)
        update_inventory(inventory, item_name, quantity_change)
        after = inventory[item_name]
        print("{:<12} {:+d}  {} -> {}".format(item_name, quantity_change, before, after))
        if after == 0 and before > 0:
            print("  warning: {} is now depleted".format(item_name))
    return inventory


def main():
    stock = {'apple': 10, 'banana': 5, 'cherry': 3}
    show_inventory(stock, "Opening stock")

    deliveries = [('apple', 5), ('durian', 12)]
    print()
    print("Applying deliveries")
    apply_transactions(stock, deliveries)

    sales = [('banana', -10), ('cherry', -1), ('apple', -4)]
    print()
    print("Applying sales")
