    print()
    show_inventory(stock, "Closing stock")

    empty = [name for name in sorted(stock) if stock[name] == 0]
    print()
    if empty:
        print("Reorder needed for:", ", ".join(empty))
    else:
        print("Nothing needs reordering")

    try:
        update_inventory(stock, 'apple', 1.5)
    except TypeError as error:
        print("rejected bad transaction:", error)


if __name__ == "__main__":
    main()

