def rotation_steps(lst, n):
    """Return the intermediate lists produced by rotating one position at a time."""
    if not lst:
        return []
    step = 1 if n >= 0 else -1
    frames = []
    current = list(lst)
    for _ in range(abs(n)):
        current = rotate_list(current, step)
        frames.append(current)
    return frames


def format_rotation(lst, n):
    """Describe a rotation as a single readable line."""
    direction = "right" if n >= 0 else "left"
    return "{} rotated {} by {} -> {}".format(lst, direction, abs(n), rotate_list(lst, n))


def normalized_shift(lst, n):
    """Smallest non-negative right-shift equivalent to n for this list."""
    if not lst:
        return 0
    return n % len(lst)


def report(lst, shifts):
    print "Source list:", lst
    print "Length:", len(lst)
    for n in shifts:
        print " ", format_rotation(lst, n)
        equivalent = normalized_shift(lst, n)
        if equivalent != n:
            print "    equivalent right shift:", equivalent


def main():
    numbers = [1, 2, 3, 4, 5]
    report(numbers, [2, -1, 0, 5, 7, -12])

    print "Original list unchanged:", numbers

    print "Step-by-step rotation of", numbers, "by 3:"
    for index, frame in enumerate(rotation_steps(numbers, 3), start=1):
        print "  step", index, "->", frame

    letters = ["a", "b", "c", "d"]
    print "Letters rotated left twice:", rotate_list(letters, -2)

    print "Empty list rotated:", rotate_list([], 4)
    print "Single element rotated:", rotate_list([9], -3)

    try:
        rotate_list([1, 2, 3], 1.5)
    except TypeError as exc:
        print "Rejected bad shift:", exc

    try:
        rotate_list("abc", 1)
    except TypeError as exc:
        print "Rejected bad sequence:", exc


if __name__ == "__main__":
    main()

