import itertools


def generate_permutations(lst):
    """Return a list of all orderings of the elements in lst."""
    return [list(perm) for perm in itertools.permutations(lst)]


def count_permutations(lst):
    """Number of permutations of lst, computed without building them."""
    total = 1
    for factor in range(2, len(lst) + 1):
        total *= factor
    return total


def format_permutation(perm):
    """Render a single permutation as a compact tuple-like string."""
    return "(" + ", ".join(repr(part) for part in perm) + ")"


def print_permutations(lst, max_shown=6):
    """Print the permutations of lst, truncating long listings."""
    perms = generate_permutations(lst)
    print("input:", lst)
    print("permutations:", len(perms), "of", count_permutations(lst), "expected")
    for perm in perms[:max_shown]:
        print("   ", format_permutation(perm))
    if len(perms) > max_shown:
        print("    ... and", len(perms) - max_shown, "more")
    return perms


def find_permutation_index(lst, target):
    """Position of target among the generated permutations, or -1."""
    wanted = list(target)
    for index, perm in enumerate(generate_permutations(lst)):
        if perm == wanted:
            return index
    return -1


def print_permutation_index(lst, target):
    """Report where target sits in the listing of permutations of lst."""
    position = find_permutation_index(lst, target)
    label = format_permutation(target)
    if position < 0:
        print(label, "is not a permutation of", lst)
    else:
        print(label, "appears at index", position)
    return position


def main():
    print_permutations([1, 2])
    print_permutations(['a'])
    print_permutations([])
    print_permutations(['x', 'y', 'z', 'w'])
    print_permutation_index([1, 2, 3], (3, 1, 2))
    print_permutation_index([1, 2, 3], (3, 3, 1))


if __name__ == "__main__":
    main()

