def _validate(text, pattern):
    if not isinstance(text, str) or not isinstance(pattern, str):
        raise TypeError("text and pattern must both be strings")
    return text, pattern


def build_failure_table(pattern):
    table = [0] * len(pattern)
    length = 0
    for i in range(1, len(pattern)):
        while length > 0 and pattern[i] != pattern[length]:
            length = table[length - 1]
        if pattern[i] == pattern[length]:
            length += 1
        table[i] = length
    return table


def find_all_occurrences(text, pattern):
    text, pattern = _validate(text, pattern)
    if not pattern:
        return []
    table = build_failure_table(pattern)
    matches = []
    length = 0
    for i, ch in enumerate(text):
        while length > 0 and ch != pattern[length]:
            length = table[length - 1]
        if ch == pattern[length]:
            length += 1
        if length == len(pattern):
            matches.append(i - length + 1)
            length = table[length - 1]
    return matches


def highlight(text, indices, width):
    marks = [" "] * len(text)
    for start in indices:
        for offset in range(width):
            marks[start + offset] = "^"
    return "".join(marks)


def report(text, pattern):
    indices = find_all_occurrences(text, pattern)
    print("text    :", repr(text))
    print("pattern :", repr(pattern))
    if not indices:
        print("result  : no occurrences")
        return indices
    print("result  :", indices)
    print("         ", text)
    print("         ", highlight(text, indices, len(pattern)))
    overlapping = [b for a, b in zip(indices, indices[1:]) if b - a < len(pattern)]
    if overlapping:
        print("note    : overlapping matches at", overlapping)
    return indices


def main():
    samples = [
        ("ababab", "aba"),
        ("hello world", "o"),
        ("aaaa", "aa"),
        ("mississippi", "issi"),
        ("abcdef", "gh"),
    ]
    total = 0
    for text, pattern in samples:
        total += len(report(text, pattern))
        print("-" * 40)
    print("total matches found:", total)
    try:
        find_all_occurrences("abc", None)
    except TypeError as err:
        print("rejected bad input:", err)


if __name__ == "__main__":
    main()

