def remove_duplicates_unordered(items):
    """Return a new list holding each distinct element of `items` exactly once."""
    if not isinstance(items, list):
        raise TypeError("remove_duplicates_unordered expects a list")
    seen = set()
    unhashable = []
    unique = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        unique.append(item)
    return unique


def duplicate_counts(items):
    """Map every repeated element to the number of times it occurs."""
    counts = {}
    for item in items:
        key = repr(item)
        counts[key] = counts.get(key, 0) + 1
    return {key: n for key, n in counts.items() if n > 1}


def report(items):
    """Print a short before/after summary for one input list."""
    unique = remove_duplicates_unordered(items)
    print("input :", items)
    print("unique:", unique)
    removed = len(items) - len(unique)
    if removed:
        print("removed", removed, "duplicate element(s)")
        for key, n in sorted(duplicate_counts(items).items()):
            print("   ", key, "appeared", n, "times")
    else:
        print("all elements were already distinct")
    return unique


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [True, 1, 1.0, 2, "2"],
        [[1], [1], [2], (3,), (3,)],
    ]
    for sample in samples:
        report(sample)
        print("-" * 40)

    total_in = sum(len(sample) for sample in samples)
    total_out = sum(len(remove_duplicates_unordered(s)) for s in samples)
    print("elements seen    :", total_in)
    print("elements retained:", total_out)

    try:
        remove_duplicates_unordered("abc")
    except TypeError as exc:
        print("rejected non-list input:", exc)


if __name__ == "__main__":
    main()

