def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0.0 for an empty list."""
    if not numbers:
        return 0.0
    return float(sum(numbers)) / len(numbers)


def parse_numbers(text):
    """Turn a comma or whitespace separated string into a list of floats."""
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        try:
            values.append(float(token))
        except ValueError:
            print("Skipping unrecognised value: {!r}".format(token))
    return values


def format_average(numbers):
    """Human readable one-line summary of a dataset's average."""
    average = calculate_average(numbers)
    if not numbers:
        return "no data -> average 0.0"
    return "n={} sum={:g} average={:.4g}".format(len(numbers), sum(numbers), average)


def deviations(numbers):
    """Distance of each value from the average, in input order."""
    average = calculate_average(numbers)
    return [value - average for value in numbers]


def report(label, numbers):
    """Print a small report for one dataset and return its average."""
    print("=== {} ===".format(label))
    print("values:", numbers)
    print(format_average(numbers))
    for value, delta in zip(numbers, deviations(numbers)):
        print("  {:g} deviates by {:+.3f}".format(value, delta))
    return calculate_average(numbers)


def main():
    averages = []
    averages.append(report("example 1", [1, 2, 3, 4, 5]))
    averages.append(report("example 2", [10, 20]))
    averages.append(report("empty", []))

    raw = "3.5, 4.5, oops, 8"
    print("=== parsed input ===")
    print("raw text:", raw)
    parsed = parse_numbers(raw)
    averages.append(report("parsed", parsed))

    print("=== overall ===")
    print("collected averages:", averages)
    print("average of averages: {:.4f}".format(calculate_average(averages)))


if __name__ == "__main__":
    main()

